        uint256 end
    ) internal pure returns (bool success, address value) {
        if (end > bytes(input).length || begin > end) return (false, address(0));

        bool hasPrefix = (end > begin + 1) && bytes2(_unsafeReadBytesOffset(bytes(input), begin)) == bytes2("0x"); // don't do out-of-bound (possibly unsafe) read if sub-string is empty
        uint256 expectedLength = 40 + hasPrefix.toUint() * 2;

        // check that input is the correct length
        if (end - begin == expectedLength) {
            // length guarantees that this does not overflow, and value is at most type(uint160).max
            (bool s, uint256 v) = _tryParseHexUintUncheckedBounds(input, begin, end);
            return (s, address(uint160(v)));
        } else {
            return (false, address(0));
        }
    }

    function _tryParseChr(bytes1 chr) private pure returns (uint8) {
        uint8 value = uint8(chr);

        // Try to parse `chr`:
        // - Case 1: [0-9]
        // - Case 2: [a-f]
        // - Case 3: [A-F]
        // - otherwise not supported
        unchecked {
            if (value > 47 && value < 58) value -= 48;
            else if (value > 96 && value < 103) value -= 87;
            else if (value > 64 && value < 71) value -= 55;
            else return type(uint8).max;
        }

        return value;
    }

    /**
     * @dev Escape special characters in JSON strings. This can be useful to prevent JSON injection in NFT metadata.
     *
     * WARNING: This function should only be used in double quoted JSON strings. Single quotes are not escaped.
     *
     * NOTE: This function escapes backslashes (including those in \uXXXX sequences) and the characters in ranges
     * defined in section 2.5 of RFC-4627 (U+0000 to U+001F, U+0022 and U+005C). All control characters in U+0000
     * to U+001F are escaped (\b, \t, \n, \f, \r use short form; others use \u00XX). ECMAScript's `JSON.parse` does
     * recover escaped unicode characters that are not in this range, but other tooling may provide different results.
     */
    function escapeJSON(string memory input) internal pure returns (string memory) {
        bytes memory buffer = bytes(input);

        // Put output at the FMP. Memory will be reserved later when we figure out the actual length of the escaped
        // string. All write are done using _unsafeWriteBytesOffset, which avoid the (expensive) length checks for
        // each character written.
        bytes memory output;
        assembly ("memory-safe") {
            output := mload(0x40)
        }
        uint256 outputLength = 0;

        for (uint256 i = 0; i < buffer.length; ++i) {
            uint8 char = uint8(bytes1(_unsafeReadBytesOffset(buffer, i)));
            if (((SPECIAL_CHARS_LOOKUP & (1 << char)) != 0)) {
                _unsafeWriteBytesOffset(output, outputLength++, "\\");
                if (char == 0x08) _unsafeWriteBytesOffset(output, outputLength++, "b");
                else if (char == 0x09) _unsafeWriteBytesOffset(output, outputLength++, "t");
                else if (char == 0x0a) _unsafeWriteBytesOffset(output, outputLength++, "n");
                else if (char == 0x0c) _unsafeWriteBytesOffset(output, outputLength++, "f");
                else if (char == 0x0d) _unsafeWriteBytesOffset(output, outputLength++, "r");
                else if (char == 0x5c) _unsafeWriteBytesOffset(output, outputLength++, "\\");
                else if (char == 0x22) {
                    // solhint-disable-next-line quotes
                    _unsafeWriteBytesOffset(output, outputLength++, '"');
                } else {
                    // U+0000 to U+001F without short form: output \u00XX
                    _unsafeWriteBytesOffset(output, outputLength++, "u");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, "0");
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char >> 4]);
                    _unsafeWriteBytesOffset(output, outputLength++, HEX_DIGITS[char & 0x0f]);
                }
            } else {
                _unsafeWriteBytesOffset(output, outputLength++, bytes1(char));
            }
        }
        // write the actual length and reserve memory
        assembly ("memory-safe") {
            mstore(output, outputLength)
            mstore(0x40, add(output, add(outputLength, 0x20)))
        }

        return string(output);
    }

    /**
     * @dev Reads a bytes32 from a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeReadBytesOffset(bytes memory buffer, uint256 offset) private pure returns (bytes32 value) {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            value := mload(add(add(buffer, 0x20), offset))
        }
    }

    /**
     * @dev Write a bytes1 to a bytes array without bounds checking.
     *
     * NOTE: making this function internal would mean it could be used with memory unsafe offset, and marking the
     * assembly block as such would prevent some optimizations.
     */
    function _unsafeWriteBytesOffset(bytes memory buffer, uint256 offset, bytes1 value) private pure {
        // This is not memory safe in the general case, but all calls to this private function are within bounds.
        assembly ("memory-safe") {
            mstore8(add(add(buffer, 0x20), offset), shr(248, value))
        }
    }
}

contracts/HelloWeb3.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/**
 * @title HelloWeb3 —— 链上留言板
 * @dev 每一次留言都会连同作者地址、时间戳被永久记录在链上，任何人可查、无人可改。
 *      作为 Solidity 入门的第一个合约，它覆盖了：
 *      状态变量、结构体、数组、事件(Event)、函数可见性、require 校验、msg.sender
 */
contract HelloWeb3 {
    /// @dev 一条留言记录
    struct Entry {
        string content;    // 留言内容
        address author;    // 留言者地址
        uint256 timestamp; // 区块时间戳
    }

    Entry[] private _history;   // 全部历史留言
    address public owner;       // 合约部署者
    uint256 public updateCount; // 留言更新次数

    /// @dev 每次留言更新时触发，前端可监听该事件做实时展示
    event MessageUpdated(
        address indexed author,
        string content,
        uint256 timestamp,
        uint256 index
    );

    constructor(string memory initialMessage) {
        owner = msg.sender;
        updateCount = 0;
        _history.push(Entry(initialMessage, msg.sender, block.timestamp));
        emit MessageUpdated(msg.sender, initialMessage, block.timestamp, 0);
    }

    /// @notice 写入一条新留言（会改变链上状态，需要支付 gas）
    function setMessage(string calldata newMessage) external {
        require(bytes(newMessage).length > 0, "message cannot be empty");
        require(bytes(newMessage).length <= 280, "message too long (max 280)");

        _history.push(Entry(newMessage, msg.sender, block.timestamp));
        updateCount += 1;
        emit MessageUpdated(
            msg.sender,
            newMessage,
            block.timestamp,
            updateCount
        );
    }

    /// @notice 读取最新一条留言（view 函数，不消耗 gas）
    function getMessage() external view returns (string memory) {
        return _history[_history.length - 1].content;
    }

    /// @notice 按序号读取某条历史留言
    function getEntry(uint256 index)
        external
        view
        returns (string memory content, address author, uint256 timestamp)
    {
        require(index < _history.length, "index out of range");
        Entry memory e = _history[index];
        return (e.content, e.author, e.timestamp);
    }

    /// @notice 历史留言总条数
    function historyLength() external view returns (uint256) {
        return _history.length;
    }
}

contracts/mocks/MaliciousActors.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";
import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {SimpleMarket} from "../SimpleMarket.sol";

/**
 * @title 测试用的恶意 / 异常合约
 *
 * 这些合约【仅用于单元测试】，绝不是要部署上线的东西。
 * 它们的作用是模拟攻击者与异常场景，用来验证我们的市场合约是否真的扛得住。
 *
 * 安全领域的一条基本原则：
 *   你不写攻击合约去打自己的合约，就永远不知道防线是否真的有效。
 *   「看起来对」和「被攻击后仍然对」是两回事。
 */

/**
 * @notice 恶意买家：收到 NFT 的瞬间尝试重入 buy()
 *
 * 攻击原理：
 *   市场用 safeTransferFrom 把 NFT 转给买家时，如果买家是合约，
 *   会回调它的 onERC721Received —— 这是一个免费的执行窗口。
 *   攻击者在窗口里再次调用 buy()，试图在挂单状态还没更新时重复购买
 *   （或者更狠的场景：把同一枚 NFT 反复卖给自己、反复套出 ETH）。
 *
 * 我们期望的结果：
 *   市场的两道防线（先改状态 + nonReentrant）会让第二次 buy 失败，
 *   reentrySucceeded 保持 false。
 */
contract MaliciousBuyer is IERC721Receiver {
    SimpleMarket public market;
    address public nft;
    uint256 public tokenId;
    uint256 public price;

    /// @notice 重入尝试次数
    uint256 public reentryAttempts;

    /// @notice 重入是否成功 —— 测试断言它必须为 false
    bool public reentrySucceeded;

    /// @notice 发起攻击：调用市场的 buy
    function attack(address marketAddr, address nftAddr, uint256 tokenId_, uint256 price_) external payable {
        market = SimpleMarket(marketAddr);
        nft = nftAddr;
        tokenId = tokenId_;
        price = price_;
        market.buy{value: price_}(nftAddr, tokenId_);
    }

    /**
     * @dev 收到 NFT 时的回调 —— 攻击窗口就在这里
     *
     * 用 try/catch 捕获失败：如果市场防护生效，重入的 buy 会 revert，
     * 被 catch 住后我们照常返回正确的 selector，让外层交易继续完成。
     * 这样测试才能走到最后去检查 reentrySucceeded == false。
     */
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external returns (bytes4) {
        reentryAttempts += 1;
        // 尝试再次购买同一枚 NFT。若防护有效，这里必然失败
        try market.buy{value: price}(nft, tokenId) {
            reentrySucceeded = true; // 如果走到这里，说明市场被打穿了
        } catch {
            // 预期路径：被 nonReentrant 或 NotListed 挡下
        }
        return IERC721Receiver.onERC721Received.selector;
    }

    /// @dev 能接收退款
    receive() external payable {}
}

/**
 * @notice 拒绝收款的卖家：用来验证「钱货两清」的原子性
 *
 * 场景：卖家是一个合约，且它的 receive 会 revert（可能是被恶意设计，
 *      也可能是多签钱包配置错误、fallback 太复杂导致 gas 不够等）。
 *
 * 我们期望的结果：
 *   市场给卖家打款失败 → 整笔交易 revert → NFT 也不转移、挂单仍有效。
 *   绝不能出现「NFT 已经给了买家，但卖家没收到钱」这种单方面损失。
 *   这就是原子性：要么全成功，要么全回滚。
 */
contract RejectingSeller is IERC721Receiver {
    /// @notice 是否拒绝接收 ETH
    bool public rejectEth;

    constructor(bool rejectEth_) {
        rejectEth = rejectEth_;
    }

    /// @dev 挂单：先授权市场，再挂单。必须由本合约持有 NFT 时调用
    function listOnMarket(address marketAddr, address nftAddr, uint256 tokenId_, uint256 price_) external {
        IERC721(nftAddr).approve(marketAddr, tokenId_);
        SimpleMarket(marketAddr).list(nftAddr, tokenId_, price_);
    }

    /// @dev 正常接收 NFT（否则挂单前的铸造都无法完成）
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external returns (bytes4) {
        return IERC721Receiver.onERC721Received.selector;
    }

    /// @dev 收 ETH 时按配置拒绝 —— 这里是触发回滚的关键
    receive() external payable {
        if (rejectEth) {
            revert("RejectingSeller: I refuse ETH");
        }
    }
}

/**
 * @notice 拒收退款的买家：能正常接收 NFT，但收不进任何 ETH
 *
 * 场景：买家多付了 ETH（前端估算偏差、抢单时多给），市场在成交末尾会把
 *      多出来的部分退回去。如果这个买家是个"只进不出"的合约 ——
 *      它的 receive 直接 revert —— 退款就会失败。
 *
 * 这个合约覆盖的是 buy() 里的最后一道分支：
 *      uint256 excess = msg.value - price;
 *      if (excess > 0) {
 *          (bool refundOk, ) = payable(msg.sender).call{value: excess}("");
 *          if (!refundOk) revert EthTransferFailed();   // ← 本合约要打的就是这里
 *      }
 *
 * 我们要验证两件事：
 *   1. 退款失败必须 revert EthTransferFailed（而不是默默吞掉多付的钱，
 *      也不是让买家白拿 NFT）；
 *   2. 整笔交易原子回滚 —— NFT 回到卖家手上、挂单依然有效、买家没收到 NFT。
 *
 * 注意它与 RejectingSeller 的区别：
 *   RejectingSeller 卡的是"给卖家打款"这一步（发生在转 NFT 之后），
 *   本合约卡的是"给买家退款"这一步（发生在最后）。
 *   两步都必须触发整体回滚，缺一不可测。
 *
 * 为什么它必须正确实现 onERC721Received？
 *   因为市场转 NFT 用的是 safeTransferFrom。如果本合约不返回正确的 selector，
 *   交易会在转 NFT 那一步就失败，根本走不到退款分支，测不到我们想测的东西。
 */
contract RefundRejectingBuyer is IERC721Receiver {
    /// @notice 本次攻击的目标市场
    SimpleMarket public market;

    /// @notice 目标 NFT 合约与编号（留档，便于在测试中回读）
    address public nft;
    uint256 public tokenId;

    /// @notice 是否真的收到过 NFT。整笔回滚后它必然是 false
    bool public receivedNft;

    /**
     * @notice 发起购买：把调用者给的 ETH 原样转发给 buy
     *
     * 调用方要带 value = price + 多付部分，且必须严格大于 price，
     * 否则 buy 里的 if (excess > 0) 走不进去，测不到退款分支。
     */
    function attack(address marketAddr, address nftAddr, uint256 tokenId_) external payable {
        market = SimpleMarket(marketAddr);
        nft = nftAddr;
        tokenId = tokenId_;
        market.buy{value: msg.value}(nftAddr, tokenId_);
    }

    /// @dev 正常接收 NFT（必须返回 selector，否则进不到退款那一步）
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external returns (bytes4) {
        receivedNft = true;
        return IERC721Receiver.onERC721Received.selector;
    }

    /// @dev 一分钱 ETH 都不收 —— 退款必然失败
    receive() external payable {
        revert("RefundRejectingBuyer: I refuse ETH");
    }

    /// @dev fallback 也堵死，避免有人用带数据的 call 绕过 receive
    fallback() external payable {
        revert("RefundRejectingBuyer: I refuse ETH");
    }
}

/**
 * @notice 拒收 ETH 的收款地址：专门用来卡 withdrawFees 的打款分支
 *
 * 场景：owner 调用 withdrawFees(to) 提取手续费，但 to 是一个拒绝收款的合约。
 *      市场里那行代码是：
 *          (bool ok, ) = payable(to).call{value: amount}("");
 *          if (!ok) revert EthTransferFailed();   // ← 本合约要打的就是这里
 *
 * 期望行为：
 *   1. 交易 revert EthTransferFailed；
 *   2. accumulatedFees【不能被清零】 —— accumulatedFees = 0 虽然写在转账之前
 *      （先改状态再转账，防重入的标准写法），但整笔回滚会让状态一起复原，
 *      钱依然记在市场账上，owner 换个地址还能再取。
 *      这种"失败即全额复原"正是我们要验证的原子性。
 */
contract EthRejectingReceiver {
    /// @notice 是否真的收到过 ETH。交易回滚后必然是 false
    bool public gotEth;

    /// @dev 收 ETH 一律拒绝
    receive() external payable {
        gotEth = true; // 这一行会随下面的 revert 一起回滚，实际永远是 false
        revert("EthRejectingReceiver: I refuse ETH");
    }

    /// @dev fallback 同样拒绝
    fallback() external payable {
        revert("EthRejectingReceiver: I refuse ETH");
    }
}

/**
 * @notice 重入探针：不只是"重入失败"，还要把失败原因带回来
 *
 * 与 MaliciousBuyer 的区别：
 *   MaliciousBuyer 用 try/catch 吞掉了重入的失败原因，只能证明"没成功"；
 *   本合约用低级 call 把 revert 数据原样存下来，于是我们能【断言失败原因本身】。
 *
 * 这一点很重要：重入被挡下的原因必须是我们预期的那个
 * （ReentrancyGuardReentrantCall，来自 nonReentrant 修饰符），
 * 而不是碰巧因为别的检查（比如挂单已失效 NotListed）而失败。
 * 只有确认了原因，才能说"nonReentrant 这道防线真的起作用了"。
 *
 * 顺带它还能把 ReentrancyGuard 那条 modifier 分支真正跑一遍 ——
 * 修饰符的 revert 分支平时极难被覆盖，必须有人在回调里重入才能打到。
 */
contract ReentrancyProbe is IERC721Receiver {
    /// @notice 目标市场 / NFT / 编号 / 出价
    SimpleMarket public market;
    address public nft;
    uint256 public tokenId;
    uint256 public price;

    /// @notice 重入是否成功 —— 期望永远为 false
    bool public reentrySucceeded;

    /// @notice 重入失败时返回的 revert 数据（前 4 字节就是错误选择器）
    bytes public reentryRevertData;

    /// @dev 正常接收 NFT（否则走不到重入那一步）
    function onERC721Received(
        address,
        address,
        uint256,
        bytes calldata
    ) external returns (bytes4) {
        // 用低级 call 重入 buy，这样即使失败也不会中断外层交易
        (bool ok, bytes memory data) = address(market).call{value: price}(
            abi.encodeWithSignature("buy(address,uint256)", nft, tokenId)
        );
        if (ok) {
            reentrySucceeded = true; // 走到这里说明市场被打穿了
        } else {
            reentryRevertData = data; // 把失败原因存下来供测试断言
        }
        return IERC721Receiver.onERC721Received.selector;
    }

    /// @notice 发起购买
    function attack(address marketAddr, address nftAddr, uint256 tokenId_) external payable {
        market = SimpleMarket(marketAddr);
        nft = nftAddr;
        tokenId = tokenId_;
        price = msg.value;
        market.buy{value: msg.value}(nftAddr, tokenId_);
    }

    /// @dev 能接收退款
    receive() external payable {}
}

/**
 * @notice 重入提现的收款方：在收到手续费的瞬间，再调一次 withdrawFees
 *
 * 场景：owner 把手续费提到某个合约地址，该合约的 receive 里又去调 withdrawFees，
 *      试图再套一次钱（此时 accumulatedFees 已经被清零，但攻击者的思路就是
 *      赌"状态还没更新"或者能绕过锁）。
 *
 * 期望结果：
 *   1. 重入调用被 nonReentrant 挡下，返回 ReentrancyGuardReentrantCall；
 *   2. 外层那笔正常提现不受影响，钱照常到账。
 *
 * 这个合约的作用是覆盖 withdrawFees 上 nonReentrant 修饰符的 revert 分支 ——
 * 修饰符分支只有在"真的有人重入"时才会被执行到，平时永远走不到。
 */
contract ReenteringFeeReceiver {
    /// @notice 目标市场
    SimpleMarket public market;

    /// @notice 重入是否成功 —— 期望永远为 false
    bool public reentrySucceeded;

    /// @notice 重入失败时返回的 revert 数据
    bytes public reentryRevertData;

    constructor(address marketAddr) {
        market = SimpleMarket(marketAddr);
    }

    /// @dev 收到手续费的瞬间尝试再提一次。用低级 call，失败也不影响外层交易
    receive() external payable {
        (bool ok, bytes memory data) = address(market).call(
            abi.encodeWithSignature("withdrawFees(address)", address(this))
        );
        if (ok) {
            reentrySucceeded = true;
        } else {
            reentryRevertData = data;
        }
    }
}

/**
 * @notice 会重入的 owner：专门用来打 withdrawFees 上 nonReentrant 那条分支
 *
 * 为什么需要这个合约：
 *   withdrawFees 的修饰符顺序是 onlyOwner → nonReentrant。
 *   普通收款方重入时，第一个修饰符 onlyOwner 就把它挡了（拿到的是
 *   OwnableUnauthorizedAccount），根本轮不到锁出场。
 *   要让 nonReentrant 的 revert 分支真正被执行，重入者必须是 owner 本人。
 *   于是我们把 owner 转移给这个合约，让它在收到提现款的瞬间再提一次。
 *
 * 期望结果：
 *   owner 自己重入也会被那把锁挡下 —— 这正是"锁不看身份，只看状态"的含义。
 */
contract ReenteringOwner {
    /// @notice 目标市场
    SimpleMarket public market;

    /// @notice 重入是否成功 —— 期望永远为 false
    bool public reentrySucceeded;

    /// @notice 重入失败时返回的 revert 数据
    bytes public reentryRevertData;

    constructor(address marketAddr) {
        market = SimpleMarket(marketAddr);
    }

    /// @notice 接受市场所有权（SimpleMarket 升级为 Ownable2Step 后需要这一步）
    function acceptOwnership() external {
        market.acceptOwnership();
    }

    /// @notice 以 owner 身份发起提现（本合约已被转移为 market 的 owner）
    /// @param to 提现收款地址，传本合约自己才能在 receive 里触发重入
    function drain(address to) external {
        market.withdrawFees(to);
    }

    /// @dev 收到提现款的瞬间，以 owner 身份再提一次
    receive() external payable {
        (bool ok, bytes memory data) = address(market).call(
            abi.encodeWithSignature("withdrawFees(address)", address(this))
        );
        if (ok) {
            reentrySucceeded = true;
        } else {
            reentryRevertData = data;
        }
    }
}

/* ==========================================================================
 * 以下三个是 EIP-2981（版税）专项测试用的合约
 * ==========================================================================
 */

/**
 * @notice 普通 ERC721 合集：故意【不】继承 ERC2981
 *
 * 用途：验证市场合约的"优雅降级"。
 * 现实背景：2021 年 EIP-2981 定稿前部署的 NFT（CryptoPunks、早期藏品）都没有
 * royaltyInfo 函数。市场如果无脑调用 IERC2981(nft).royaltyInfo(...)，
 * 会因为没有这个函数而 revert，结果是这些 NFT 在本市场【根本卖不掉】。
 *
 * 正确做法（市场里已实现）：先 IERC165.supportsInterface(0x2a55205a)，
 * 返回 false 就直接跳过版税。本合约 supportsInterface(0x2a55205a) 返回 false，
 * 因为 ERC721 基础实现只认 ERC721 / ERC721Metadata / ERC165 三个 id。
 */
contract PlainERC721 is ERC721 {
    uint256 private _nextId = 1;

    constructor() ERC721("PlainNFT", "PNFT") {}

    /// @notice 无门槛铸造，方便测试随意造 NFT
    function mint(address to) external returns (uint256 tokenId) {
        tokenId = _nextId++;
        _safeMint(to, tokenId);
    }
}

/**
 * @notice 拒收 ETH 的版税收款方
 *
 * 用途：验证 Pull Payment 的核心价值 —— 版税收款方出问题，只影响它自己提现，
 * 【不】影响成交。
 *
 * 对照实验（本合约存在的意义）：
 *   若市场写成 push（buy 里直接给 receiver 转账）：
 *       receiver 拒收 → buy 整体 revert → 卖家卖不掉、买家买不到，
 *       一个跟交易无关的第三方把整条链路拖死（DoS）
 *   写成 pull（现在的做法）：
 *       成交照常成功，版税只是记在 pendingRoyalties 里；
 *       receiver 什么时候能收，是它自己的事
 */
contract RoyaltyRejectingReceiver {
    /// @notice 是否收到过 ETH —— 期望永远为 false（收到就 revert，状态被回滚）
    bool public gotEth;

    /// @notice 提现入口，供测试调用
    function withdraw(address marketAddr) external {
        SimpleMarket(marketAddr).withdrawRoyalties();
    }

    /// @dev 收到任何 ETH 都立刻回滚
    receive() external payable {
        gotEth = true;
        revert("RoyaltyRejectingReceiver: I refuse ETH");
    }

    fallback() external payable {
        revert("RoyaltyRejectingReceiver: I refuse ETH");
    }
}

/**
 * @notice 重入提现的版税收款方：收到版税的瞬间，再调一次 withdrawRoyalties()
 *
 * 与 ReenteringFeeReceiver 的区别：
 *   withdrawRoyalties 没有 onlyOwner，任何被指定为版税接收者的地址都能调用，
 *   所以这里不需要"先把 owner 转移给合约"这道手续，攻击面反而更直接 ——
 *   这也说明【开放给任意人的提现函数，锁的价值更大】。
 *
 * 期望结果：
 *   1. 重入被 nonReentrant 挡下，返回 ReentrancyGuardReentrantCall
 *   2. 外层正常提现不受影响，钱照常到账
 */
contract ReenteringRoyaltyReceiver {
    /// @notice 目标市场
    SimpleMarket public market;

    /// @notice 重入是否成功 —— 期望永远为 false
    bool public reentrySucceeded;

    /// @notice 重入失败时返回的 revert 数据
    bytes public reentryRevertData;

    /// @notice 收到的版税总额
    uint256 public received;

    constructor(address marketAddr) {
        market = SimpleMarket(marketAddr);
    }

    /// @notice 提取属于自己的版税（触发 receive → 重入）
    function withdraw() external {
        market.withdrawRoyalties();
    }

    /// @dev 收到版税的瞬间尝试再提一次。用低级 call，失败也不影响外层交易
    receive() external payable {
        received += msg.value;
        (bool ok, bytes memory data) = address(market).call(
            abi.encodeWithSignature("withdrawRoyalties()")
        );
        if (ok) {
            reentrySucceeded = true;
        } else {
            reentryRevertData = data;
        }
    }
}

/**
 * @notice 拒收 ETH 的出价者：能正常出价，但任何打给它的 ETH 都会 revert
 *
 * 它要验的是两条不同的路径：
 *   1. 自己 withdrawOffer  → 市场 revert EthTransferFailed（整体回滚）
 *      这是合理的：调用者就是收款人，回滚后钱仍记在它的出价里，随时可重试
 *   2. 持有者 rejectOffer  → 市场【不能】revert，必须把钱转入 pendingWithdrawals
 *      否则一个拒收者就能让持有者永远拒绝不了任何出价（DoS）
 *
 * 它同时是 IERC721Receiver：万一持有者接受它的出价，它能正常收下 NFT，
 * 这样"恶意出价者不阻塞成交"才有被验证的余地。
 */
contract RejectingOfferBidder is IERC721Receiver {
    SimpleMarket public market;
    address public nft;
    uint256 public tokenId;

    /// @notice 累计出价额
    uint256 public offered;

    /// @notice 是否收到了 NFT
    bool public gotNft;

    /// @notice 拒收开关：true = 拒收一切 ETH，false = 正常接收
    ///         有了它，同一个 mock 就能把"退回失败 → 入待领池 → 改过自新 → 领回"整条链路跑完
    bool public rejectEth = true;

    /// @notice 重入探针结果：收到钱的瞬间再调一次 withdrawOffer / withdrawPendingFunds
    ///         两个都期望失败 —— 锁还在生效，错误是 ReentrancyGuardReentrantCall
    bool public withdrawReentrySucceeded;
    bytes public withdrawReentryRevertData;
    bool public pendingReentrySucceeded;
    bytes public pendingReentryRevertData;

    function setRejectEth(bool rejectEth_) external {
        rejectEth = rejectEth_;
    }

    /// @notice 出价：把随交易带来的 ETH 原样转给市场
    function makeOffer(address marketAddr, address nftAddr, uint256 tokenId_) external payable {
        market = SimpleMarket(marketAddr);
        nft = nftAddr;
        tokenId = tokenId_;
        offered += msg.value;
        market.makeOffer{value: msg.value}(nftAddr, tokenId_);
    }

    /// @notice 尝试自己取回出价 —— 拒收期间这笔调用必然失败
    function withdrawOffer() external {
        market.withdrawOffer(nft, tokenId);
    }

    /// @notice 从待领池领钱（拒收期间会失败；关掉拒收后应成功）
    function claimPending() external {
        market.withdrawPendingFunds();
    }

    function onERC721Received(address, address, uint256, bytes calldata)
        external
        returns (bytes4)
    {
        gotNft = true;
        return IERC721Receiver.onERC721Received.selector;
    }

    /// @dev 重入探针：用低级 call，失败也不影响外层交易
    function _probe(bytes memory callData, bool isPending) internal {
        (bool ok, bytes memory data) = address(market).call(callData);
        if (isPending) {
            if (ok) {
                pendingReentrySucceeded = true;
            } else {
                pendingReentryRevertData = data;
            }
        } else {
            if (ok) {
                withdrawReentrySucceeded = true;
            } else {
                withdrawReentryRevertData = data;
            }
        }
    }

    /// @dev 拒收开关打开时拒收一切 ETH；关掉后，收钱的同时重入一次
    receive() external payable {
        if (rejectEth) {
            revert("RejectingOfferBidder: I refuse ETH");
        }
        if (nft != address(0)) {
            _probe(
                abi.encodeWithSignature("withdrawOffer(address,uint256)", nft, tokenId),
                false
            );
            _probe(abi.encodeWithSignature("withdrawPendingFunds()"), true);
        }
    }
}

/**
 * @notice 在 onERC721Received 回调里重入 acceptOffer 的恶意出价者
 *
 * 攻击路径：
 *   持有者 acceptOffer → _settleSale → safeTransferFrom(持有者 → 本合约)
 *   → ERC721 回调 onERC721Received → 本合约再次调用 acceptOffer
 *
 * 期望结果（两道防线都要验）：
 *   1. 重入被 nonReentrant 挡下，错误是 ReentrancyGuardReentrantCall
 *      —— 锁在修饰符里，比函数体的任何检查都先执行，所以拿到的是锁而不是 NoActiveOffer
 *   2. 外层那笔正常成交照常完成：NFT 到手、卖家收到钱
 *
 * 与 ReentrancyProbe 的区别：那边重入的是 buy（挂单路径），
 * 这边重入的是 acceptOffer（出价路径），验证新功能继承了同样的防护强度。
 */
contract ReenteringOfferBidder is IERC721Receiver {
    SimpleMarket public market;
    address public nft;
    uint256 public tokenId;

    /// @notice 重入是否成功 —— 期望永远为 false
    bool public reentrySucceeded;

    /// @notice 重入失败时返回的 revert 数据（前 4 字节是错误选择器）
    bytes public reentryRevertData;

    /// @notice 顺手再重入一次 rejectOffer 的结果 —— 同样期望被锁挡下
    ///         此刻 NFT 已经归本合约所有（ownerOf 在回调前就已更新），
    ///         身份检查是过得去的，唯一挡得住它的只有那把锁
    bool public rejectReentrySucceeded;
    bytes public rejectReentryRevertData;

    /// @notice 出价：把随交易带来的 ETH 原样转给市场
    function makeOffer(address marketAddr, address nftAddr, uint256 tokenId_) external payable {
        market = SimpleMarket(marketAddr);
        nft = nftAddr;
        tokenId = tokenId_;
        market.makeOffer{value: msg.value}(nftAddr, tokenId_);
    }

    /// @dev 收到 NFT 的瞬间重入 acceptOffer。用低级 call：失败也不影响外层交易
    function onERC721Received(address, address, uint256, bytes calldata)
        external
        returns (bytes4)
    {
        (bool ok, bytes memory data) = address(market).call(
            abi.encodeWithSignature(
                "acceptOffer(address,uint256,address)",
                nft,
                tokenId,
                address(this)
            )
        );
        if (ok) {
            reentrySucceeded = true; // 走到这里说明市场被打穿了
        } else {
            reentryRevertData = data; // 把失败原因存下来供测试断言
        }

        // 同一次回调里再试一次 rejectOffer：此刻 NFT 已归本合约所有，身份检查是过得去的，
        // 也就是说没有锁的话这次调用真能改状态 —— 所以锁必须把它也挡下来
        (bool rejectOk, bytes memory rejectData) = address(market).call(
            abi.encodeWithSignature(
                "rejectOffer(address,uint256,address)",
                nft,
                tokenId,
                address(this)
            )
        );
        if (rejectOk) {
            rejectReentrySucceeded = true;
        } else {
            rejectReentryRevertData = rejectData;
        }
        return IERC721Receiver.onERC721Received.selector;
    }

    /// @dev 能接收退款
    receive() external payable {}
}

/**
 * @notice 专测 fulfillListing（EIP-712 链下签名成交）的恶意买家
 *
 * 为什么不能复用 RefundRejectingBuyer：
 *   那个合约调的是 market.buy()，走的是「链上挂单」这条入口。
 *   fulfillListing 是另一条完全独立的成交入口（跳过 list() 直接成交），
 *   它有自己的退款分支与重入窗口，必须单独拿一个探针去打。
 *
 * 两个开关，一个合约覆盖两条分支：
 *   rejectEth = true → 拒收 ETH：验证「多付的钱退不回去时，整笔成交必须回滚」
 *   reenter   = true → 收 NFT 的瞬间重入 fulfillListing：验证 nonReentrant 锁
 *
 * 这里刻意不在 onERC721Received 里让重入失败冒泡：
 *   真实攻击者就是这样「吞掉失败、继续完成交易」的，
 *   我们正是要靠这种方式观察锁到底有没有生效，而不是被 revert 掩盖掉。
 */
contract FulfillListingProbe is IERC721Receiver {
    SimpleMarket public market;

    bool public rejectEth;
    bool public reenter;

    /// @dev 重入时要原样复用的成交参数
    SimpleMarket.ListingIntent public intent;
    address public seller;
    bytes public signature;

    bool public receivedNft;
    bool public reentrySucceeded;
    bytes public reentryRevertData;

    constructor(bool rejectEth_, bool reenter_) {
        rejectEth = rejectEth_;
        reenter = reenter_;
    }

    function attack(
        address marketAddr,
        SimpleMarket.ListingIntent calldata intent_,
        address seller_,
        bytes calldata signature_
    ) external payable {
        market = SimpleMarket(marketAddr);
        intent = intent_;
        seller = seller_;
        signature = signature_;
        market.fulfillListing{value: msg.value}(intent_, seller_, signature_);
    }

    function onERC721Received(address, address, uint256, bytes calldata)
        external
        returns (bytes4)
    {
        receivedNft = true;

        if (reenter) {
            bytes memory callData = abi.encodeWithSelector(
                SimpleMarket.fulfillListing.selector,
                intent,
                seller,
                signature
            );
            // 用合约当前余额再打一次同一笔成交：若锁失效，这里会成功
            (bool ok, bytes memory data) = address(market).call{value: address(this).balance}(
                callData
            );
            if (ok) {
                reentrySucceeded = true; // 走到这里说明市场被打穿了
            } else {
                reentryRevertData = data; // 把失败原因存下来供测试断言
            }
        }

        return IERC721Receiver.onERC721Received.selector;
    }

    /// @dev rejectEth 打开时拒收一切 ETH，用于逼出退款失败分支
    receive() external payable {
        if (rejectEth) revert("FulfillListingProbe: I refuse ETH");
    }
}

contracts/MultiSigOwner.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/**
 * @title MultiSigOwner —— 2/3 多签治理合约
 *
 * ============================================================================
 * 一、为什么要这个合约（一句话：消灭单点故障）
 * ============================================================================
 *
 * 现在的 SimpleMarket / MyNFT 是 Ownable2Step —— 【一个地址说了算】。
 * 这个地址（0xe3C2...fCd8）的私钥一旦出现下面任何一种情况，项目就完了：
 *   · 私钥泄露 / 电脑中毒 / 被钓鱼签了恶意交易
 *   · 私钥丢失（硬盘坏、助记词没备份）
 *   · 持有人作恶（自己改费率、卷走手续费、随便暂停合约）
 *
 * 多签就是把"一把钥匙"换成"三把钥匙里凑两把才能开门"：
 *
 *   3 个 owner，阈值(threshold) = 2
 *   任何一次 owner 操作（改费率、提手续费、暂停合约、mint）
 *   都必须至少 2 个人点头才能执行。
 *
 * 这是主网上线前【最该补的一课】。历史上因为单人 owner 出事的案例数不清：
 *   · 2021 年 PAID Network：owner 私钥泄露，攻击者直接 mint 了 5900 万个代币
 *   · 2021 年 Uranium Finance / 2022 年 Nomad / 2023 年无数小项目……
 * 共同点不是代码有 bug，而是【权限太集中】。
 *
 * ============================================================================
 * 二、它怎么接手市场的所有权（关键：两步走）
 * ============================================================================
 *
 * SimpleMarket 用的是 Ownable2Step，转让 owner 必须走两步：
 *
 *   第 1 步（现任 owner 发起）：
 *     market.transferOwnership(multisigAddress)
 *     → 只是"提名"，owner 还是旧的，新 owner 地址存进 pendingOwner
 *
 *   第 2 步（新 owner 确认 —— 这里是多签）：
 *     multisig 内部提议 → 2 人确认 → 执行
 *     market.acceptOwnership()          ← 这笔交易的 msg.sender 是多签合约地址
 *     → owner 正式变成多签合约
 *
 * 为什么要两步？防止你把 owner 转给一个【打错的地址 / 不支持该操作的合约】，
 * 那样权限就永久锁死了。两步走让接收方必须"亲自表态"。
 *
 * 之后市场的所有 onlyOwner 操作，都要走多签流程：
 *   某人 submit(market, 0, setFeeBps(300) 的 calldata)
 *   → 另一人 confirm(0)
 *   → 任意人 execute(0)   ← 合约用 call 发这笔交易，msg.sender == 多签地址
 *   → market.owner() 看到的是多签地址，校验通过 ✓
 *
 * ============================================================================
 * 三、状态机：一笔多签交易的生命周期
 * ============================================================================
 *
 *   submit()            confirmations = 1（提交者自动投第一票）
 *      │
 *      ├─ confirm()     confirmations = 2  ── 达到阈值
 *      │      │                                  │
 *      │      └─ execute() ─────────────────────┘  → 真正发出 call，executed = true
 *      │
 *      └─ revoke()      撤票，confirmations 减 1（后悔药，执行前都能撤）
 *
 * 三个铁律：
 *   1. 提交者自动投第一票（避免"提了不算数"的尴尬，也省一笔 gas）
 *   2. 执行前随时可以撤票
 *   3. 执行后（executed = true）一切冻结，不能再确认、不能重复执行
 *
 * ============================================================================
 * 四、安全设计（逐条对应 Slither 考点）
 * ============================================================================
 *
 * 1) 用 call，绝不用 delegatecall
 *    delegatecall 会在【本合约的存储】上执行别人的代码 —— 那等于把多签的
 *    owners / threshold 暴露给被调用方改。多签只需要"替市场发一笔交易"，
 *    用 call 就够了（被调方的存储是它自己的）。
 *    这是 Gnosis Safe 用 delegatecall 而我不用的原因：Safe 需要模块化扩展，
 *    我们不需要 —— 简单就是安全。
 *
 * 2) Checks-Effects-Interactions（先改状态，再外部调用）
 *    execute() 里先把 executed 置 true，再发 call。
 *    如果被调用方是恶意合约、在回调里再入 execute()，
 *    会撞上 AlreadyExecuted 直接 revert —— 重入门都没开。
 *
 * 3) 低阶 call 必须检查返回值
 *    (success, data) = to.call(...)，失败就 revert 整笔交易。
 *    不做检查的话：交易"看起来成功"了（executed=true），
 *    但目标合约其实没执行 —— 钱 / 状态凭空消失。
 *
 * 4) 阈值与 owner 数量的不变式（invariant）
 *    0 < threshold <= owners.length，任何时候都成立。
 *    移除 owner 时如果阈值超出了，自动把阈值下调到 owner 数量。
 *    没有这条，移除一个人就可能让多签【永久锁死】（谁都凑不够票）。
 *
 * 5) 管理函数只能"自己调自己"
 *    addOwner / removeOwner / changeThreshold 用 onlySelf 保护，
 *    唯一调用路径是多签流程本身：
 *      submit(address(this), 0, addOwner(newGuy) 的 calldata) → confirm → execute
 *    也就是说：换人、改规则，同样需要 2/3 同意。
 *    如果留一个 onlyOwner 的后门，那"一个人就能把自己加进来" —— 多签白做。
 *
 * 6) 没有自毁、没有代理、没有 upgrade
 *    规则写死在链上，谁都改不了（包括我们）。这是缺点也是优点：
 *    出事没法打补丁，但黑客也没法打补丁。
 *
 * ============================================================================
 * 五、已知取舍（诚实列出，不藏着）
 * ============================================================================
 *
 * · owners 数组用 swap-and-pop 删除，【不保证顺序】。
 *   顺序对多签没有意义（权威状态是 isOwner 映射），但如果你要按顺序展示，
 *   读出来之后自己在前端排序。
 * · 没有"时间锁（timelock）"：2 人同意后立刻执行，没有延迟窗口。
 *   真要做时间锁，是下一个迭代的事（见路线图 P1）。
 * · 没有"提案过期"机制：老提案一直挂着，靠人自觉不执行。
 * · execute 允许【任何人】调用（达到阈值后），方便外包 gas。
 *   执行人不必须是 owner —— 因为能不能执行只取决于票数，不取决于谁发起。
 */
contract MultiSigOwner {
    // ========================================================================
    // 数据结构
    // ========================================================================

    /**
     * @notice 一笔待执行的多签交易
     * @param to            目标合约（比如市场合约地址）
     * @param value         随交易发送的 ETH（提手续费时是 0，分钱时是金额）
     * @param data          调用数据（函数选择器 + 参数编码）
     * @param confirmations 已确认票数
     * @param executed      是否已执行
     */
    struct Transaction {
        address to;
        uint256 value;
        bytes data;
        uint256 confirmations;
        bool executed;
    }

    // ========================================================================
    // 状态变量
    // ========================================================================

    /// @notice 多签成员列表（删除时不保序，见文件头"已知取舍"）
    address[] private _owners;

    /// @notice 某地址是否为多签成员 —— 权限判断的【唯一权威】来源
    mapping(address => bool) public isOwner;

    /// @notice 执行阈值：至少多少票才能执行
    uint256 public threshold;

    /// @notice 所有提案，索引即 txId
    Transaction[] private _transactions;

    /// @notice txId => owner => 是否已确认
    mapping(uint256 => mapping(address => bool)) public isConfirmedBy;

    // ========================================================================
    // 事件
    // ========================================================================

    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event ThresholdChanged(uint256 oldThreshold, uint256 newThreshold);
    event Submitted(uint256 indexed txId, address indexed proposer, address indexed to, uint256 value, bytes data);
    event Confirmed(uint256 indexed txId, address indexed owner, uint256 confirmations);
    event Revoked(uint256 indexed txId, address indexed owner, uint256 confirmations);
    event Executed(uint256 indexed txId, address indexed to, uint256 value, bool success);
    event Received(address indexed sender, uint256 amount);

    // ========================================================================
    // 自定义错误（比 require 字符串省 gas，且前端能拿到错误类型）
    // ========================================================================

    error ZeroAddress();
    error EmptyOwners();
    error DuplicateOwner(address owner);
    error NotAnOwner();
    error AlreadyAnOwner();
    error OwnerNotFound();
    error CannotRemoveLastOwner();
    error ThresholdCannotBeZero();
    error InvalidThreshold(uint256 provided, uint256 maxAllowed);
    error TxDoesNotExist(uint256 txId);
    error AlreadyConfirmed(uint256 txId, address owner);
    error NotConfirmedYet(uint256 txId, address owner);
    error AlreadyExecuted(uint256 txId);
    error BelowThreshold(uint256 confirmations, uint256 threshold);
    error ExecutionFailed(uint256 txId);
    error OnlySelf();

    // ========================================================================
    // 修饰器
    // ========================================================================

    /// @dev 只有多签成员能调用
    modifier onlyOwner() {
        if (!isOwner[msg.sender]) revert NotAnOwner();
        _;
    }

    /**
     * @dev 只有多签合约【自己】能调用
     *      用于保护管理函数：换人 / 改阈值必须走 submit → confirm → execute
     */
    modifier onlySelf() {
        if (msg.sender != address(this)) revert OnlySelf();
        _;
    }

    modifier txExists(uint256 txId) {
        if (txId >= _transactions.length) revert TxDoesNotExist(txId);
        _;
    }

    modifier notExecuted(uint256 txId) {
        if (_transactions[txId].executed) revert AlreadyExecuted(txId);
        _;
    }

    modifier notConfirmed(uint256 txId) {
        if (isConfirmedBy[txId][msg.sender]) revert AlreadyConfirmed(txId, msg.sender);
        _;
    }

    // ========================================================================
    // 构造与收款
    // ========================================================================

    /**
     * @notice 部署多签
     * @param owners_    成员地址数组（建议 3 个【互相独立】的地址）
     * @param threshold_ 执行阈值（3 人时建议 2）
     *
     * ⚠️ 部署检查清单（错了没法改，只能重新部署）：
     *   1. 三个地址必须是【你独立控制】的三个不同私钥（冷钱包 / 另一台电脑 / 硬件钱包）
     *      放同一个电脑上的三个账户 = 多签形同虚设，一台机器中毒全没了
     *   2. 别用交易所地址、合约地址当 owner（它们不会帮你确认）
     *   3. threshold 不要设成 1（等于没签）也不要设成 3（一个人失联就锁死）
     */
    constructor(address[] memory owners_, uint256 threshold_) {
        if (owners_.length == 0) revert EmptyOwners();
        if (threshold_ == 0) revert ThresholdCannotBeZero();
        // 不变式：threshold 不能超过成员数，否则永远凑不够票 = 永久锁死
        if (threshold_ > owners_.length) revert InvalidThreshold(threshold_, owners_.length);

        for (uint256 i = 0; i < owners_.length; ++i) {
            address owner = owners_[i];
            if (owner == address(0)) revert ZeroAddress();
            if (isOwner[owner]) revert DuplicateOwner(owner);
            isOwner[owner] = true;
            _owners.push(owner);
            emit OwnerAdded(owner);
        }

        threshold = threshold_;
        emit ThresholdChanged(0, threshold_);
    }

    /**
     * @notice 接收 ETH —— 必须要有，否则市场手续费提不出来
     *         市场是 Pull 模式：withdrawFees 把钱打给 owner（也就是本合约）
     */
    receive() external payable {
        emit Received(msg.sender, msg.value);
    }

    // ========================================================================
    // 核心流程：submit → confirm → execute（revoke 是后悔药）
    // ========================================================================

    /**
     * @notice 提交一笔待执行交易，并自动投第一票
     * @param to    目标合约地址
     * @param value 随交易发送的 ETH（wei）
     * @param data  调用数据，用 abi.encodeWithSignature 生成
     * @return txId 提案编号，后续 confirm / revoke / execute 都用它
     *
     * 为什么提交即投票？
     *   一个人花 gas 提交了提案，说明他同意 —— 否则逻辑上说不通。
     *   这样 2/3 时只需【再 1 个人确认】即可执行，省一笔交易。
     *   （Gnosis Safe 不自动投票，因为它的提案人可以是中立的中继者；
     *    我们自己用，提交即同意更自然。）
     */
    function submit(address to, uint256 value, bytes calldata data)
        external
        onlyOwner
        returns (uint256 txId)
    {
        if (to == address(0)) revert ZeroAddress();

        txId = _transactions.length;
        _transactions.push(
            Transaction({
                to: to,
                value: value,
                data: data,
                confirmations: 0,
                executed: false
            })
        );

        emit Submitted(txId, msg.sender, to, value, data);

        // 内部调用不改 msg.sender，投的就是提交者这一票
        _confirm(txId);
    }

    /**
     * @notice 确认某个提案（投赞成票）
     * @param txId 提案编号
     */
    function confirm(uint256 txId) external onlyOwner txExists(txId) notExecuted(txId) notConfirmed(txId) {
        _confirm(txId);
    }

    /**
     * @notice 撤回自己的确认票（执行前随时可撤）
     * @param txId 提案编号
     */
    function revoke(uint256 txId) external onlyOwner txExists(txId) notExecuted(txId) {
        if (!isConfirmedBy[txId][msg.sender]) revert NotConfirmedYet(txId, msg.sender);

        isConfirmedBy[txId][msg.sender] = false;
        _transactions[txId].confirmations -= 1;

        emit Revoked(txId, msg.sender, _transactions[txId].confirmations);
    }

    /**
     * @notice 执行提案 —— 票数够了才能真正发出这笔交易
     * @param txId 提案编号
     * @return success    目标调用是否成功
     * @return returnData 目标调用的返回数据
     *
     * 谁都能调：执行只取决于票数，不取决于谁发起。
     * 这样"A 提议、B 确认"之后，可以让 C（甚至不是 owner）付 gas 去执行。
     *
     * CEI 说明：先置 executed = true（Effects），再 call（Interactions）。
     * 恶意目标合约若回调 execute，第二行修饰符就会 revert。
     */
    function execute(uint256 txId)
        external
        txExists(txId)
        notExecuted(txId)
        returns (bool success, bytes memory returnData)
    {
        Transaction storage transaction = _transactions[txId];

        if (transaction.confirmations < threshold) {
            revert BelowThreshold(transaction.confirmations, threshold);
        }

        // 顺序不能乱：先改状态 → 先记账（事件）→ 最后才做外部交互。
        // 恶意目标合约若回调 execute，会撞上 AlreadyExecuted；
        // 而 call 失败会整笔回滚，上面记的账也一并撤销，绝不会留下"半执行"状态。
        transaction.executed = true;
        emit Executed(txId, transaction.to, transaction.value, true);

        (success, returnData) = transaction.to.call{value: transaction.value}(transaction.data);

        // 低阶 call 不检查返回值 = 静默失败，必须显式处理
        if (!success) revert ExecutionFailed(txId);
    }

    /// @dev 内部投票逻辑，submit 与 confirm 共用
    function _confirm(uint256 txId) private {
        isConfirmedBy[txId][msg.sender] = true;
        _transactions[txId].confirmations += 1;
        emit Confirmed(txId, msg.sender, _transactions[txId].confirmations);
    }

    // ========================================================================
    // 自管理：只能通过多签流程（submit → confirm → execute）触发
    // ========================================================================

    /**
     * @notice 新增一个多签成员
     * @dev 调用方式：submit(address(multisig), 0, abi.encodeWithSignature("addOwner(address)", guy))
     */
    function addOwner(address newOwner) external onlySelf {
        if (newOwner == address(0)) revert ZeroAddress();
        if (isOwner[newOwner]) revert AlreadyAnOwner();

        isOwner[newOwner] = true;
        _owners.push(newOwner);
        emit OwnerAdded(newOwner);
    }

    /**
     * @notice 移除一个多签成员
     * @dev 若移除后 threshold 超过剩余人数，阈值自动下调 —— 防止永久锁死
     */
    function removeOwner(address owner) external onlySelf {
        if (!isOwner[owner]) revert OwnerNotFound();
        // 一个人都不剩 = 合约里的钱和权限全部锁死
        if (_owners.length <= 1) revert CannotRemoveLastOwner();

        isOwner[owner] = false;

        // swap-and-pop：把最后一个元素搬到被删位置再弹出，省 gas
        // 代价是顺序会变（对多签无影响，权威状态是 isOwner 映射）
        uint256 last = _owners.length - 1;
        uint256 index = _owners.length;
        for (uint256 i = 0; i <= last; ++i) {
            if (_owners[i] == owner) {
                index = i;
                break;
            }
        }
        // isOwner 已确认存在，理论上必定找到；留一道保险防止状态不一致
        if (index >= _owners.length) revert OwnerNotFound();

        _owners[index] = _owners[last];
        _owners.pop();

        emit OwnerRemoved(owner);

        // 维持不变式：threshold <= owners.length
        if (threshold > _owners.length) {
            uint256 old = threshold;
            threshold = _owners.length;
            emit ThresholdChanged(old, threshold);
        }
    }

    /**
     * @notice 修改执行阈值
     * @dev 调用方式：submit(address(multisig), 0, abi.encodeWithSignature("changeThreshold(uint256)", 3))
     */
    function changeThreshold(uint256 newThreshold) external onlySelf {
        if (newThreshold == 0) revert ThresholdCannotBeZero();
        if (newThreshold > _owners.length) revert InvalidThreshold(newThreshold, _owners.length);

        emit ThresholdChanged(threshold, newThreshold);
        threshold = newThreshold;
    }

    // ========================================================================
    // 视图函数
    // ========================================================================

    /// @notice 当前所有多签成员（顺序不保证）
    function getOwners() external view returns (address[] memory) {
        return _owners;
    }

    /// @notice 提案总数（最新 txId = 总数 - 1）
    function getTransactionCount() external view returns (uint256) {
        return _transactions.length;
    }

    /// @notice 读取某个提案的完整信息
    function getTransaction(uint256 txId)
        external
        view
        returns (address to, uint256 value, bytes memory data, uint256 confirmations, bool executed)
    {
        Transaction storage transaction = _transactions[txId];
        return (
            transaction.to,
            transaction.value,
            transaction.data,
            transaction.confirmations,
            transaction.executed
        );
    }
}

contracts/MyNFT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721URIStorage} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import {ERC721Enumerable} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721Enumerable.sol";
import {ERC2981} from "@openzeppelin/contracts/token/common/ERC2981.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title MyNFT —— 一份用来学习 ERC721（NFT 标准）的教学合约
 *
 * ============================================================================
 * 一、ERC721 与 ERC20 的本质区别（这是理解 NFT 的第一关）
 * ============================================================================
 *
 * ERC20（同质化代币，FT）：
 *   - 账本结构是 mapping(address => uint256)，记录"某地址有多少币"
 *   - 每一枚币完全等价，你的 1 MTK 和我的 1 MTK 没有任何区别，可以互换（fungible）
 *   - 所以 ERC20 只有 "余额" 概念，没有 "哪一枚" 的概念
 *   - transfer(to, amount)：转的是一个**数量**
 *
 * ERC721（非同质化代币，NFT）：
 *   - 账本结构是 mapping(uint256 => address)，记录"第 N 号 token 归谁"
 *   - 每个 tokenId 全局唯一、不可互换、不可分割（non-fungible）
 *   - 所以 ERC721 没有 amount 参数，只有 tokenId
 *   - transferFrom(from, to, tokenId)：转的是一个**具体编号的物件**
 *
 *   类比：ERC20 是银行账户里的钱（只关心金额），ERC721 是房产证（关心是哪一套房）。
 *
 * 由此带来 API 上的连锁差异：
 *   ERC20：balanceOf(owner) -> uint256（我有多少钱）
 *   ERC721：balanceOf(owner) -> uint256（我有几个 NFT） + ownerOf(tokenId) -> address（这个 NFT 归谁）
 *   ERC20：transfer(to, amount)           ERC721：transferFrom(from, to, tokenId)
 *   ERC20：approve(spender, amount)       ERC721：approve(spender, tokenId) / setApprovalForAll(operator, true)
 *
 * ============================================================================
 * 二、为什么继承四个合约（多重继承的"菱形问题"）
 * ============================================================================
 *
 *   ERC721            基础实现：ownerOf / transferFrom / approve / 事件
 *     ├── ERC721URIStorage   给每个 tokenId 存一份独立的 metadata 链接（tokenURI）
 *     └── ERC721Enumerable   提供"枚举"能力：totalSupply / tokenOfOwnerByIndex
 *   ERC2981           版税标准（EIP-2981）：royaltyInfo + _setDefaultRoyalty / _setTokenRoyalty
 *   Ownable           权限控制：onlyOwner 修饰符
 *
 * 这四个父合约里有三个都重写了同一个底层函数（_update / supportsInterface / tokenURI），
 * Solidity 的多重继承要求：当多个父合约都覆写了同一个函数时，子合约必须显式
 * 再覆写一次并列出所有父合约，否则编译器报 "Derived contract must override function"。
 * 这就是下面那几个 override(...) 的由来，详见文末 "四、为什么必须 override"。
 *
 * ============================================================================
 * 二点五、EIP-2981 版税到底解决了什么（本次新增的核心）
 * ============================================================================
 *
 * 背景：传统艺术市场里，画家把画卖给画廊后，画廊再加价转卖 —— 画家一分钱拿不到。
 *      NFT 让"二次销售分成"在技术上第一次变得可行：每一笔转卖都能自动给创作者分钱。
 *      这就是版税（royalty）。
 *
 * EIP-2981 定义的东西【极少】，只有一个函数：
 *
 *      function royaltyInfo(uint256 tokenId, uint256 salePrice)
 *          external view returns (address receiver, uint256 royaltyAmount);
 *
 * 它的语义是："如果这枚 tokenId 以 salePrice 成交，请给 receiver 打 royaltyAmount 这么多钱。"
 *
 * 三个必须记住的关键点：
 *
 *   1) 它是【只读的报价单】，不是自动扣款。
 *      标准只规定"怎么问"，不规定"必须付"。
 *      真正付不付、付多少，取决于市场合约（也就是我们的 SimpleMarket）自觉调用它。
 *      这就是为什么有的市场（如早期的 Sudoswap、Blur）会"绕开版税"：
 *      标准本身没有任何强制力，纯粹靠市场自觉与生态共识。
 *
 *   2) 金额单位用【基点】（basis points）：分母固定 10000。
 *      500 表示 5%，250 表示 2.5%。整数运算，绝不用浮点。
 *      注意 OZ 的实现里 royaltyAmount = salePrice * royaltyFraction / 10000，
 *      是【向下取整】的 —— 余数怎么处理，是市场合约的责任（我们让余数归卖家）。
 *
 *   3) 它【只认 tokenId，不认买卖双方】。
 *      同一个合集里，#1 可以是 5%、#2 可以是 10%（_setTokenRoyalty），
 *      没有单独设置过的 token 走默认版税（_setDefaultRoyalty）。
 *      但标准无法表达"只在某几个市场收版税"或"只收前三次转卖"这类复杂规则，
 *      那些要靠市场侧自己扩展。
 *
 * 为什么市场侧必须用 ERC165 做能力检测？
 *      因为 2021 年之前部署的海量 NFT 合约根本不认识 EIP-2981，
 *      直接调 royaltyInfo 会因"函数不存在"而 revert。
 *      结果是：不支持版税的老 NFT 在你的市场里根本卖不掉。
 *      所以正确姿势是：
 *          if (IERC165(nft).supportsInterface(0x2a55205a)) { ...查版税... } else { ...跳过... }
 *      0x2a55205a 就是 IERC2981 的 interfaceId（royaltyInfo 一个函数选择器的值）。
 * ============================================================================
 */
contract MyNFT is ERC721, ERC721URIStorage, ERC721Enumerable, ERC2981, Ownable2Step, Pausable {
    // ========================================================================
    // 状态变量
    // ========================================================================

    /// @notice 下一个待铸造的 tokenId。从 1 开始（0 会与"不存在"的语义混淆）
    uint256 private _nextTokenId;

    /// @notice 铸造上限（本次学习项目设为 10000）
    /// @dev immutable：构造后不再改写，读取时免一次 SLOAD，每次铸造都省 gas
    uint256 public immutable maxSupply;

    /// @notice 累计铸造数量（只增不减，即使销毁也不回退）
    uint256 public totalMinted;

    /// @notice 是否开放"任何人都能铸造"的公开铸造（默认关闭）
    bool public publicMintEnabled;

    // ========================================================================
    // 自定义错误（Solidity 0.8.4+ 推荐做法：比 require 字符串省 gas，且可携带参数）
    // ========================================================================

    /// @notice 铸造数量超过上限
    error ExceedsMaxSupply(uint256 requested, uint256 maxSupply);

    /// @notice 公开铸造未开启
    error PublicMintDisabled();

    /// @notice tokenURI 不能为空（空 URI 意味着 NFT 没有 metadata，钱包里会显示成空白方块）
    error EmptyTokenURI();

    /// @notice 没有销毁权限（既不是持有者，也没有被授权）
    error NotAuthorizedToBurn(address caller, uint256 tokenId);

    // ========================================================================
    // 事件
    // ========================================================================

    /// @notice 公开铸造开关被切换
    event PublicMintToggled(bool enabled);

    /// @notice 默认版税被更新（OZ 的 _setDefaultRoyalty 不 emit 事件，我们自己补一个，
    ///         否则前端与市场无法监听"版税率变了"这件事）
    event DefaultRoyaltyUpdated(address indexed receiver, uint96 feeNumerator);

    /// @notice 单枚 token 的版税被单独设置
    event TokenRoyaltyUpdated(uint256 indexed tokenId, address indexed receiver, uint96 feeNumerator);

    /// @notice 单枚 token 的版税被清除，回退到默认版税
    event TokenRoyaltyReset(uint256 indexed tokenId);

    // ========================================================================
    // 构造函数
    // ========================================================================

    /**
     * @param initialOwner        合约 owner（OpenZeppelin v5 强制要求显式传入，v4 时代默认 msg.sender）
     * @param maxSupply_          铸造上限
     * @param royaltyReceiver     版税接收者（创作者地址）。传 address(0) 表示"本次不设版税"，
     *                            之后仍可由 owner 调用 setDefaultRoyalty 补上
     * @param royaltyFeeNumerator 版税分子，分母固定 10000。500 = 5%，250 = 2.5%
     *
     * 注意初始化父合约的写法：ERC721("名称", "符号") 里这两个字符串就是
     * 钱包 / 市场里显示的 NFT 合集名与代号，由 ERC721Metadata 的 name() / symbol() 暴露。
     *
     * 兼容说明：本轮把构造函数从 2 个参数扩到 4 个参数。Solidity 不支持构造函数重载，
     * 所以所有部署点（测试 fixture 与 scripts/deploy-mynft.js）都必须同步带上后两个参数；
     * 想维持"无版税"的老行为，就传 (address(0), 0)。
     */
    constructor(
        address initialOwner,
        uint256 maxSupply_,
        address royaltyReceiver,
        uint96 royaltyFeeNumerator
    ) ERC721("MyNFT", "MNFT") Ownable(initialOwner) {
        require(maxSupply_ > 0, "maxSupply must be > 0");
        maxSupply = maxSupply_;
        _nextTokenId = 1; // 从 1 开始编号
        publicMintEnabled = false; // 默认只有 owner 能铸造

        // 版税：零地址表示"暂不设版税"。OZ 的 _setDefaultRoyalty 本身会拒绝零地址，
        // 这里提前判断是为了保留"先部署、后补设"的灵活性
        if (royaltyReceiver != address(0)) {
            _setDefaultRoyalty(royaltyReceiver, royaltyFeeNumerator);
        }
    }

    // ========================================================================
    // 铸造
    // ========================================================================

    /**
     * @notice owner 定向铸造：把新 NFT 铸造给指定地址
     * @param to  接收者
     * @param uri 该 token 的 metadata 链接（通常是 ipfs://... 或 https://...）
     * @return 铸造出来的 tokenId
     *
     * 为什么用 _safeMint 而不是 _mint？见下方【_safeMint 与 _mint 的区别】。
     */
    function safeMint(address to, string calldata uri) external onlyOwner whenNotPaused returns (uint256) {
        return _mintInternal(to, uri);
    }

    /**
     * @notice 公开铸造：任何人调用都会铸造给自己（msg.sender），可由 owner 开关
     *
     * 真实项目里这里通常还会加：单次限购、白名单（Merkle Tree）、铸造价格（msg.value）等。
     * 本合约为了聚焦学习，只保留"开关"这个最简形态。
     */
    function publicMint(string calldata uri) external whenNotPaused returns (uint256) {
        if (!publicMintEnabled) {
            revert PublicMintDisabled();
        }
        return _mintInternal(msg.sender, uri);
    }

    /**
     * @notice 【教学专用】允许 owner 指定 tokenId 铸造
     *
     * 存在的唯一目的：让你可以亲手验证"同一个 tokenId 不能被铸造两次"。
     * 正常业务里不应该开放指定 tokenId 的能力（容易被抢注 / 打乱编号）。
     * 当你用同一个 tokenId 调第二次时，会 revert：ERC721InvalidSender(address(0))
     */
    function adminMintWithTokenId(address to, uint256 tokenId, string calldata uri) external onlyOwner whenNotPaused {
        if (bytes(uri).length == 0) revert EmptyTokenURI();
        // 与 _mintInternal 保持同样的 CEI 顺序：先记账，再做会回调接收者的外部调用
        totalMinted += 1;
        _safeMint(to, tokenId);
        _setTokenURI(tokenId, uri);
    }

    /// @dev 内部铸造逻辑：分配 ID → 铸造 → 绑定 metadata → 计数
    function _mintInternal(address to, string calldata uri) private returns (uint256 tokenId) {
        if (bytes(uri).length == 0) revert EmptyTokenURI();
        if (totalMinted >= maxSupply) {
            revert ExceedsMaxSupply(totalMinted + 1, maxSupply);
        }

        tokenId = _nextTokenId;
        _nextTokenId += 1;

        // CEI：先把账记上，再做会回调接收者的外部调用。
        // _safeMint 内部会回调 to 的 onERC721Received，理论上存在重入窗口；
        // 提前自增 totalMinted 后，即便发生重入，供应量计数也已是正确值。
        totalMinted += 1;

        _safeMint(to, tokenId); // 铸造：内部会 emit Transfer(address(0), to, tokenId)
        _setTokenURI(tokenId, uri); // 绑定 metadata 链接
    }

    /*
     * ==========================================================================
     * 【知识点】_safeMint 与 _mint 的区别（面试与实战都常考）
     * ==========================================================================
     *
     * _mint(to, tokenId)：
     *   只做一件事 —— 把 tokenId 的所有权写进 _owners 映射，emit Transfer 事件。
     *   它**不检查** to 是不是能处理 NFT 的合约。
     *   如果 to 是一个合约地址，而这个合约没有实现 IERC721Receiver.onERC721Received()，
     *   那么这枚 NFT 就被永久锁死在那个合约里 —— 谁也转不出来（因为转出需要合约主动调用
     *   transferFrom，而合约没写这段逻辑）。这就是著名的 "NFT stuck in contract" 事故。
     *
     * _safeMint(to, tokenId)：
     *   先执行 _mint，然后额外做一次"接收方安全检查"：
     *     if (to 是合约地址) {
     *         调用 to.onERC721Received(msg.sender, address(0), tokenId, data)
     *         要求必须返回魔法值 0x150b7a02（IERC721Receiver.onERC721Received.selector）
     *         返回值不对 / 没实现 / 调用失败 → 整个交易 revert
     *     }
     *     if (to 是普通钱包地址) 直接放行（EOA 没有代码，无需检查）
     *
     * 代价：多一次外部调用，gas 会贵一些（约 +2k~10k，取决于接收合约实现）。
     * 结论：**对外开放的铸造一律用 _safeMint**，_mint 只在你能 100% 确定接收方是 EOA
     * 或者是你自己写的可信合约时才用。OpenZeppelin 的注释里也明确写了
     * "Usage of this method is discouraged, use {_safeMint} whenever possible"。
     *
     * 同理，转账侧也有两个版本：
     *   transferFrom(from, to, tokenId)      —— 不检查接收方，可能把 NFT 转进黑洞合约
     *   safeTransferFrom(from, to, tokenId)  —— 检查接收方（可选再带一个 bytes data 参数）
     * ==========================================================================
     */

    // ========================================================================
    // 销毁
    // ========================================================================

    /**
     * @notice 销毁一枚 NFT。持有者本人、或持有者授权过的地址（approve / setApprovalForAll）可调用
     *
     * 销毁后：
     *   - ownerOf(tokenId) 会 revert（ERC721NonexistentToken）
     *   - ERC721Enumerable.totalSupply() 减 1
     *   - 但 totalMinted 不减（它是历史累计值，用来做"已铸造过多少"的统计）
     */
    function burn(uint256 tokenId) external {
        // 局部变量不叫 owner，避免遮蔽 Ownable.owner()（Slither shadowing-local）
        address tokenOwner = ownerOf(tokenId); // tokenId 不存在时这里就会 revert ERC721NonexistentToken
        if (!_isAuthorized(tokenOwner, msg.sender, tokenId)) {
            revert NotAuthorizedToBurn(msg.sender, tokenId);
        }
        _burn(tokenId);
    }

    // ========================================================================
    // 管理
    // ========================================================================

    /**
     * @notice 紧急暂停：阻断所有铸造（safeMint / publicMint / adminMintWithTokenId）
     *
     * 只挡"新增供给"，不挡转移 / 销毁 / 查询 —— 已持有 NFT 的用户在暂停期间依然能正常转卖。
     */
    function pause() external onlyOwner {
        _pause();
    }

    /// @notice 解除暂停
    function unpause() external onlyOwner {
        _unpause();
    }

    /// @notice 切换公开铸造开关（仅 owner）
    function setPublicMintEnabled(bool enabled) external onlyOwner {
        publicMintEnabled = enabled;
        emit PublicMintToggled(enabled);
    }

    // ========================================================================
    // 版税管理（EIP-2981，仅 owner）
    // ========================================================================

    /*
     * 为什么还要自己包一层 onlyOwner 的函数？
     *   OZ 提供的 _setDefaultRoyalty / _setTokenRoyalty 是 internal 的，外部调不到，
     *   而且【不 emit 任何事件】。对外暴露的 setter 要解决三件事：
     *     1. 权限：谁能改版税率（这里限定 owner；真实项目里常见做法是给版税接收者
     *        单独一个角色，或干脆部署后永久不可改 —— 用来向藏家证明不会乱来）
     *     2. 可观测：发事件，让前端 / 市场 / 索引服务能感知变化
     *     3. 校验：OZ 内部已经做了两道校验（接收者非零、分子不超过分母），
     *        越界会 revert ERC2981InvalidDefaultRoyalty / ERC2981InvalidDefaultRoyaltyReceiver
     *
     * 想让某枚 token 回到默认版税：把它的分子设成 0 是【不够】的 ——
     *   0 表示"这枚 token 版税为 0"，依然会覆盖默认值。
     *   要真正回退，用下面的 resetTokenRoyalty（内部调 _resetTokenRoyalty 删掉这条记录）。
     */

    /**
     * @notice 设置全合约默认版税
     * @param receiver     版税接收者（不能是零地址）
     * @param feeNumerator 版税分子，分母 10000。500 = 5%
     */
    function setDefaultRoyalty(address receiver, uint96 feeNumerator) external onlyOwner {
        _setDefaultRoyalty(receiver, feeNumerator);
        emit DefaultRoyaltyUpdated(receiver, feeNumerator);
    }

    /**
     * @notice 给某一枚 token 单独设置版税（优先级高于默认版税）
     * @param tokenId      目标 token
     * @param receiver     版税接收者（不能是零地址）
     * @param feeNumerator 版税分子，分母 10000。1000 = 10%
     */
    function setTokenRoyalty(
        uint256 tokenId,
        address receiver,
        uint96 feeNumerator
    ) external onlyOwner {
        _setTokenRoyalty(tokenId, receiver, feeNumerator);
        emit TokenRoyaltyUpdated(tokenId, receiver, feeNumerator);
    }

    /// @notice 清除某枚 token 的单独版税，让它回退到默认版税
    function resetTokenRoyalty(uint256 tokenId) external onlyOwner {
        _resetTokenRoyalty(tokenId);
        emit TokenRoyaltyReset(tokenId);
    }

    /// @notice 版税分母（默认 10000，前端算百分比时直接读它，别把 10000 硬编码在自己代码里）
    function royaltyDenominator() external pure returns (uint96) {
        return _feeDenominator();
    }

    // ========================================================================
    // 查询辅助
    // ========================================================================

    /// @notice 下一个将被铸造的 tokenId（前端常用来展示"即将铸造 #N"）
    function nextTokenId() external view returns (uint256) {
        return _nextTokenId;
    }

    /*
     * ==========================================================================
     * 【知识点】tokenURI 与 metadata JSON 的关系
     * ==========================================================================
     *
     * 链上只存了这一条信息：tokenId -> 一个 URI 字符串（例如 ipfs://QmXXX/1.json）。
     * **图片、名称、属性全都存在链下**，由这个 URI 指向的 JSON 文件描述。
     *
     * 调用链是这样的：
     *   钱包/市场 调 tokenURI(1)
     *        -> 返回 "ipfs://QmXxx.../1.json"
     *   钱包/市场 去 IPFS 网关取这个 JSON（例如 https://ipfs.io/ipfs/QmXxx.../1.json）
     *        -> 拿到下面这段 JSON
     *   钱包/市场 解析 JSON，读取 image 字段再取图片，显示给用户
     *
     * 标准 metadata JSON 长这样（本项目已放在 metadata/nft-metadata-example.json）：
     *
     * {
     *   "name": "MyNFT #1",
     *   "description": "我亲手铸造的第一枚 NFT",
     *   "image": "ipfs://QmYyy.../1.png",
     *   "external_url": "https://example.com/nft/1",
     *   "attributes": [
     *     { "trait_type": "Generation", "value": "Genesis" },
     *     { "trait_type": "Level",      "value": 1, "display_type": "number" },
     *     { "trait_type": "Rarity",     "value": "Common" }
     *   ]
     * }
     *
     * 关键字段：
     *   name        —— 单枚 NFT 的名字（区别于合集名 name()）
     *   description —— 描述
     *   image       —— 图片链接，OpenSea 等市场就是渲染它
     *   attributes  —— 属性数组，市场用它做"稀有度筛选"和"特征统计"
     *
     * 为什么 image 通常指向 IPFS 而不是 https？
     *   - IPFS 是内容寻址：URI 里带的是内容哈希（QmXxx...），内容一改哈希就变，无法偷偷换图
     *   - 抗单点故障：不依赖某一台服务器活着。用 https://my-server.com/1.png 的话，
     *     服务器一关、域名一过期，你的 NFT 就变成空白方块 —— 这在圈内叫 "rug metadata"
     *   - 代价：需要有人 pin（固定）住文件，否则没人访问时可能被节点垃圾回收。
     *     主流做法是付费给 Pinata / NFT.Storage / Infura 这类 pinning 服务
     *
     * 进阶方案（了解即可）：
     *   - 完全链上 NFT：把 SVG 或 metadata 直接编码进合约返回（base64 data URI），
     *     永不下线，但部署 gas 很贵
     *   - ERC4906：本合约继承的 ERC721URIStorage 实现了它，metadata 变更时会 emit
     *     MetadataUpdate 事件，让市场知道该刷新缓存
     * ==========================================================================
     */

    // ========================================================================
    // 以下四个函数是多重继承必须显式覆写的部分
    // ========================================================================

    /*
     * ==========================================================================
     * 【知识点】为什么必须 override supportsInterface
     * ==========================================================================
     *
     * ERC165 解决的是"自报家门"问题：外部合约（比如 OpenSea 的交易合约）拿到一个地址，
     * 怎么知道它支持哪些接口？答案就是调 supportsInterface(interfaceId)，
     * 参数是一组函数选择器的异或值（XOR），返回 true 表示"我支持"。
     *
     * 本合约有四个父合约都想往这个判断里"加码"：
     *   ERC721            -> 支持 IERC721(0x80ac58cd)、IERC721Metadata(0x5b5e139f)
     *   ERC721Enumerable  -> 额外支持 IERC721Enumerable(0x780e9d63)
     *   ERC721URIStorage  -> 额外支持 IERC4906(0x49064906)
     *   ERC2981           -> 额外支持 IERC2981(0x2a55205a)   ← 本轮新增，版税的"身份证"
     *
     * 由于它们各自只写了 super.supportsInterface(...)，如果不在这里汇总，
     * 编译器无法确定调用顺序，直接报错。显式写成 super 调用链后，四者会依次判断，
     * 最终"我支持 ERC721 + Metadata + Enumerable + ERC4906 + ERC2981"这个完整答案
     * 才能对外正确表达。
     *
     * 现实影响：不覆写或覆写漏了，市场可能识别不出你的 NFT 支持枚举 / metadata 更新 / 版税，
     * 表现为"在 OpenSea 上看不到图片刷新"、"卖出去创作者却拿不到版税"这类玄学问题。
     *
     * 【0x2a55205a 是怎么来的？】
     *   interfaceId = 该接口里所有函数选择器的 XOR。
     *   IERC2981 只有一个函数 royaltyInfo(uint256,uint256)，
     *   所以 interfaceId == bytes4(keccak256("royaltyInfo(uint256,uint256)")) == 0x2a55205a。
     *   验证方式：在 hardhat console 里执行
     *     ethers.id("royaltyInfo(uint256,uint256)").slice(0, 10)   // '0x2a55205a'
     * ==========================================================================
     */
    function supportsInterface(
        bytes4 interfaceId
    ) public view override(ERC721, ERC721Enumerable, ERC721URIStorage, ERC2981) returns (bool) {
        return super.supportsInterface(interfaceId);
    }

    /**
     * @dev tokenURI：ERC721 基础实现是 "baseURI + tokenId"，
     *      URIStorage 改成 "每个 tokenId 存独立字符串"，两者冲突，必须显式指定走哪个。
     *      这里 super.tokenURI() 会命中 ERC721URIStorage 的实现（它先检查 base，
     *      base 为空时返回我们 _setTokenURI 存进去的那条 URI）。
     */
    function tokenURI(
        uint256 tokenId
    ) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        return super.tokenURI(tokenId);
    }

    /**
     * @dev _update 是 ERC721 v5 的核心内部函数，所有铸造 / 转账 / 销毁最终都走它。
     *      ERC721Enumerable 覆写了它，用来维护下面这些额外的索引结构：
     *        _allTokens[]                      全局 token 列表
     *        _allTokensIndex[tokenId]          tokenId -> 在全局列表中的位置
     *        _ownedTokens[owner][index]        某地址拥有的第 index 个 tokenId
     *        _ownedTokensIndex[tokenId]        tokenId -> 在拥有者列表中的位置
     *
     *      【ERC721Enumerable 的作用与 gas 代价】
     *      作用：基础 ERC721 只有 ownerOf(tokenId)，无法回答"这个地址有哪些 NFT"。
     *            补上枚举后就能实现：
     *              totalSupply()                        合约现存 NFT 总数
     *              tokenByIndex(i)                      第 i 个 NFT 的 tokenId
     *              tokenOfOwnerByIndex(owner, i)        某地址的第 i 个 NFT
     *            前端"我的 NFT 收藏夹"、市场"浏览全部"全都依赖它。
     *
     *      代价：每次铸造 / 转账 / 销毁都要额外写 4 个 storage slot，
     *            单次 mint 的 gas 大约从 7 万涨到 14 万左右（翻倍）。
     *            删除时用 swap-and-pop（把最后一个元素搬到被删位置再 pop），
     *            所以**枚举顺序不稳定**：转账后 tokenOfOwnerByIndex 的返回顺序可能变化，
     *            业务代码绝不能依赖这个顺序。
     *
     *      什么时候可以不用它？
     *        - 纯链上游戏道具、只需要 ownerOf 判断归属：省掉它，gas 省一半
     *        - 需要"列出某个地址的所有 NFT"：必须用它，或者自己在合约里维护一套索引，
     *          再或者（更主流的做法）干脆不在链上枚举，改用 The Graph / Alchemy NFT API
     *          这类链下索引服务去扫 Transfer 事件
     */
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override(ERC721, ERC721Enumerable) returns (address) {
        return super._update(to, tokenId, auth);
    }

    /**
     * @dev 菱形继承必须补的转发钩子 —— 删不掉，但也跑不到。
     *
     * 为什么删不掉：
     *      ERC721 与 ERC721Enumerable 都声明了 _increaseBalance，
     *      C3 线性化强制要求最终合约显式 override，否则根本编译不过。
     *
     * 为什么覆盖率打不上（这条最重要）：
     *      OZ 5.6.1 的 ERC721._update 已经**不再调用**这个钩子了，
     *      它把增减余额直接内联成了 `_balances[to] += 1`。
     *      所以本函数在正常铸造流程里根本不可达 —— 它不是"测试漏了"，
     *      而是**库版本演进留下的死代码**，保留它纯粹为了满足编译要求。
     *
     * 那"禁止批量铸造"的约束还在不在：
     *      在。ERC721Enumerable 的实现是
     *      `if (amount > 0) revert ERC721EnumerableForbiddenBatchMint();`
     *      只是如今只有在有人显式调用这个钩子时才会触发，
     *      而本合约只提供单枚铸造（safeMint / publicMint / adminMintWithTokenId），
     *      没有任何批量入口，所以这条约束在当前设计下用不上，风险为零。
     *      （真要做空投，请看 ERC721Consecutive / ERC-2309，别硬塞进 Enumerable。）
     */
    function _increaseBalance(
        address account,
        uint128 amount
    ) internal override(ERC721, ERC721Enumerable) {
        super._increaseBalance(account, amount);
    }
}

/*
 * ==========================================================================
 * 附：本合约涉及的 OpenZeppelin v5 内置错误速查（写测试时要用）
 * ==========================================================================
 *
 *   ERC721NonexistentToken(tokenId)                        查询/操作了不存在的 tokenId
 *   ERC721InvalidOwner(address(0))                         balanceOf 传入零地址
 *   ERC721InvalidReceiver(address)                         铸造或转入的接收方是零地址
 *   ERC721InvalidSender(address(0))                        铸造了一个已存在的 tokenId（重复 ID）
 *   ERC721IncorrectOwner(sender, tokenId, realOwner)       转账时 from 参数不是真正的持有者
 *   ERC721InsufficientApproval(operator, tokenId)          调用者既不是持有者也没被授权
 *   ERC721OutOfBoundsIndex(owner, index)                   Enumerable 的索引越界（owner=0 表示全局越界）
 *   ERC721EnumerableForbiddenBatchMint()                   尝试批量铸造（Enumerable 不支持）
 *   OwnableUnauthorizedAccount(account)                    非 owner 调用 onlyOwner 函数
 *
 * EIP-2981（版税）内置错误，写测试时会用到：
 *   ERC2981InvalidDefaultRoyalty(numerator, denominator)   默认版税分子 > 10000（超过 100%）
 *   ERC2981InvalidDefaultRoyaltyReceiver(address(0))       默认版税接收者是零地址
 *   ERC2981InvalidTokenRoyalty(tokenId, numerator, denominator)  单枚 token 版税 > 100%
 *   ERC2981InvalidTokenRoyaltyReceiver(tokenId, address(0))      单枚 token 版税接收者是零地址
 *
 * 本项目自定义错误：
 *   ExceedsMaxSupply(requested, maxSupply)
 *   PublicMintDisabled()
 *   EmptyTokenURI()
 *   NotAuthorizedToBurn(caller, tokenId)
 * ==========================================================================
 */

contracts/MyToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

// OpenZeppelin v5 导入路径说明：
//   @openzeppelin/contracts/token/ERC20/ERC20.sol          —— ERC20 标准的基础实现
//   @openzeppelin/contracts/token/ERC20/extensions/...     —— 官方扩展（燃烧、快照、投票等）
//   @openzeppelin/contracts/access/Ownable.sol             —— 最简权限模型：单一 owner
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Burnable} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title MyToken —— 基于 OpenZeppelin 的标准 ERC20 代币（学习实践版）
 *
 * @dev 【为什么要继承，而不是自己写？】
 *      ERC20 是一套被行业验证过的接口标准，自己手写容易在边界条件上出错
 *      （例如转账 0 值、授权竞态、事件缺失等）。OpenZeppelin 的实现经过
 *      多次审计与实战检验，继承它是业界默认做法。
 *
 *      本合约同时继承三个父类，Solidity 支持多重继承：
 *        - ERC20         : 提供 totalSupply / balanceOf / transfer / approve /
 *                          allowance / transferFrom 全套标准接口，以及内部的
 *                          _mint / _burn / _update / _approve 等底层钩子。
 *        - ERC20Burnable : 在 ERC20 之上增加 burn(amount) 与 burnFrom(account, amount)，
 *                          让任何持币人都能销毁自己手里的代币。
 *        - Ownable       : 提供 owner 状态变量、onlyOwner 修饰符、
 *                          transferOwnership / renounceOwnership，
 *                          以及 modifier onlyOwner 做函数调用权限控制。
 *
 *      【继承顺序的含义】Solidity 要求「最底层、最基础」的父合约写在最前面
 *      （C3 线性化规则）。ERC20 是根基，ERC20Burnable 是它的扩展，
 *      Ownable 独立，因此顺序为 ERC20, ERC20Burnable, Ownable。
 */
contract MyToken is ERC20, ERC20Burnable, Ownable {
    /// @dev 代币精度（小数位数）。ERC20 标准是 18，与 ETH 保持一致，
    ///      意味着 1 个代币在链上实际存储为 1 * 10^18 个最小单位。
    uint8 private constant DECIMALS = 18;

    /**
     * @param initialOwner    合约部署后拥有 owner 权限的地址（可 mint / burn）
     * @param initialSupply   初始发行量，单位是「整币」（例如 1000000 表示 100 万枚），
     *                        构造函数内部会按 DECIMALS 把它放大成链上整数。
     */
    constructor(
        address initialOwner,
        uint256 initialSupply
    )
        ERC20("MyToken", "MTK") // 父合约构造：ERC20(name, symbol)
        Ownable(initialOwner) // 父合约构造：Ownable(initialOwner)，v5 起必须显式传入
    {
        // _mint 是 ERC20 内部的「铸造」函数：
        //   - 给 to 地址增加 amount 余额
        //   - 增加 totalSupply
        //   - 触发 Transfer(address(0), to, amount) 事件
        //     注意事件里 from 是零地址，链上浏览器据此识别为「铸造」。
        // 它本身不带权限校验，因此「谁能调用它」必须由我们自己控制：
        // 这里放在构造函数里，意味着只在部署时执行一次，天然安全。
        _mint(initialOwner, initialSupply * 10 ** DECIMALS);
    }

    /**
     * @notice 增发代币（只有 owner 能调用）
     * @dev 【权限修饰符 onlyOwner】这是 Ownable 提供的 modifier。
     *      它等价于在函数体最前面插入：
     *          require(msg.sender == owner(), "Ownable: caller is not the owner");
     *      若调用者不是 owner，交易会 revert（回滚），状态不被修改，
     *      错误信息为 OwnableUnauthorizedAccount(address caller)。
     *      modifier 是 Solidity 复用「前置/后置校验逻辑」的标准写法，
     *      比在每个函数里手写 require 更清晰、更不容易漏。
     *
     *      【为什么 mint 要受控】无限增发会稀释所有持币人的资产，
     *      是代币经济模型的核心风险点，所以必须收敛权限。
     */
    function mint(address to, uint256 amount) external onlyOwner {
        // amount 的单位是「最小单位」（即已含 18 位小数），
        // 与 transfer/balanceOf 等标准接口保持一致，避免调用方混淆。
        _mint(to, amount);
    }

    /**
     * @notice 从指定地址销毁代币（只有 owner 能调用）
     * @dev 与 ERC20Burnable.burn() 的区别：
     *        burn(amount)          —— 任何人都只能烧「自己」的币
     *        burnFrom(acc, amount) —— 烧别人的币，但需要先获得对方的 approve 授权（扣 allowance）
     *      本函数是第三种：由 owner 强制销毁任意地址的代币，属于高权限操作，
     *      实际项目中通常用于锁仓回收、错误补偿等场景，需谨慎使用。
     *
     *      _burn 是 ERC20 内部「销毁」函数：
     *        - 减少 account 的余额（余额不足会自动 revert）
     *        - 减少 totalSupply
     *        - 触发 Transfer(account, address(0), amount) 事件
     */
    function burn(address account, uint256 amount) external onlyOwner {
        _burn(account, amount);
    }

    /**
     * @notice 代币精度，覆盖 ERC20 默认的 18
     * @dev 【decimals 到底有什么用】
     *      链上只存整数，不存在「小数点」。decimals() 是给前端/钱包看的
     *      「显示规则」：余额 1500000000000000000（1.5e18）配合 decimals=18，
     *      前端就显示成 1.5。因此它只影响展示，不影响任何链上数学运算。
     *      绝大多数代币都用 18（与 ETH 对齐）；USDC 是特例，用 6。
     *      本函数仅作教学演示，返回值与默认值一致。
     */
    function decimals() public pure virtual override returns (uint8) {
        return DECIMALS;
    }
}

contracts/SimpleMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import {IERC2981} from "@openzeppelin/contracts/interfaces/IERC2981.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Ownable2Step} from "@openzeppelin/contracts/access/Ownable2Step.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {EIP712} from "@openzeppelin/contracts/utils/cryptography/EIP712.sol";
import {SignatureChecker} from "@openzeppelin/contracts/utils/cryptography/SignatureChecker.sol";

/**
 * @title SimpleMarket —— 一个最简 NFT 市场（挂单 / 购买 / 撤单 / 手续费 / 版税 / 提现）
 *
 * ============================================================================
 * 一、这个合约在做什么
 * ============================================================================
 *
 * 它解决一个撮合问题：卖家想把某枚 NFT 卖 X ETH，买家愿意付，双方互不信任。
 * 市场合约充当可信中间人，保证「付钱」和「交货」要么同时发生，要么都不发生。
 *
 * 注意它【不持有】NFT 和 ETH（手续费除外）：
 *   · NFT 成交时才从卖家直接转给买家，市场只是被授权代为操作
 *   · ETH 也是从买家直接打到卖家，市场只是过一手计算
 * 这叫【授权式（approval-based）】，是 OpenSea Seaport、Blur 等主流市场采用的方式。
 *
 * 另一种做法是【托管式（escrow）】：挂单时把 NFT 转入市场合约保管。
 * 为什么不这么做？
 *   1. 资产集中：合约里堆着大量 NFT，一旦合约出事就是系统性损失
 *   2. 浪费 gas：挂单一次转账、撤单又一次转账
 *   3. 挂单期间 NFT 不在自己手上，卖家的其他操作（如抵押）会受影响
 * 授权式只在成交瞬间动一次 NFT，gas 和风险都更低。
 *
 * ============================================================================
 * 二、挂单的本质 = 一次 approve
 * ============================================================================
 *
 * 卖家调用 list(nft, tokenId, price) 之前，必须先对市场合约授权：
 *
 *   nft.approve(marketAddress, tokenId)              —— 单枚授权（推荐）
 *   或 nft.setApprovalForAll(marketAddress, true)    —— 全量授权（市场常用，风险高）
 *
 * 这就是你上一轮亲手练过的东西在市场里的真实用途。
 * 顺带复习风险：市场页面让你签的 setApprovalForAll，一旦签了，
 * 该市场合约（或钓鱼合约）随时能转走你该系列的全部 NFT，且授权不会自动失效。
 * 所以 list() 里我们硬性校验授权状态，没授权直接拒绝挂单。
 *
 * ============================================================================
 * 三、本合约涉及的核心安全考点（写市场合约最容易出事的地方）
 * ============================================================================
 *
 * 1) 重入攻击（Reentrancy）—— 本合约用两道防线
 *    危险写法：先给卖家转 ETH，再转 NFT。
 *    如果卖家是恶意合约，它收到 ETH 时会在 fallback 里回调 buy()，
 *    此时挂单状态还没更新，它会再买一次……直到把钱掏空。
 *
 *    防线 A：Checks-Effects-Interactions（检查-生效-交互）
 *      先把挂单标记失效、先累计手续费（改状态），
 *      再做所有外部调用（转 NFT、转 ETH）。
 *      这样重入进来时状态已经是「已售出」，第二次 buy 在第一行检查就失败。
 *
 *    防线 B：ReentrancyGuard 的 nonReentrant 修饰符
 *      互斥锁，同一笔交易内不允许嵌套进入。
 *
 *    两道都用 —— 这是纵深防御，安全领域不信任单一机制。
 *
 * 2) Pull Payment（拉取式付款）而不是 Push
 *    平台手续费不直接转给 owner，而是累加到 accumulatedFees，
 *    由 owner 主动调用 withdrawFees 提取。
 *    原因：如果 owner 是某个合约且它拒绝收款（或它的 fallback 很耗 gas），
 *    直接转账会导致【所有人的交易都失败】—— 一个人拖垮整个市场。
 *    这是经典的「拒绝服务」陷阱。
 *
 * 3) 陈旧挂单（Stale Listing）
 *    卖家挂单后，可能把 NFT 转走了，也可能撤销了对市场的授权。
 *    此时挂单记录还在，但已经无法成交。
 *    所以 buy() 要重新校验当前持有者是否仍是挂单时的卖家。
 *
 * 4) 费用计算用基点（basis points）
 *    feeBps：10000 = 100%，250 = 2.5%。整数运算，避免浮点。
 *    并设 10% 的硬上限，防止 owner 手滑（或作恶）把手续费设成 100%。
 *
 * 5) 多余的 ETH 要退还
 *    买家可能多付（前端估算偏差、或同时有多人抢同一单）。
 *    多付的部分必须退回去，不能默默吞掉。
 *
 * 6) 版税（EIP-2981）的三条铁律 —— 本轮新增，见下一节详述
 *    a. 用 ERC165 做能力检测，不支持就跳过，绝不让老 NFT 卖不掉
 *    b. 版税与手续费一样走 Pull Payment，绝不在 buy() 里直接 push 给创作者
 *    c. 平台费 + 版税 + 卖家实得 三者之和【恒等于】成交价，
 *       整数除法产生的 1~2 wei 余数明确归卖家，合约里不留取不出的钱
 *
 * ============================================================================
 * 三点五、版税（EIP-2981）在市场侧的实现要点
 * ============================================================================
 *
 * 一笔成交价 price 的完整去向：
 *
 *        price
 *          ├── 平台手续费 fee      = price * feeBps / 10000       → accumulatedFees（owner 提）
 *          ├── 创作者版税 royalty  = price * royaltyBps / 10000   → pendingRoyalties（创作者提）
 *          └── 卖家实得 proceeds   = price - fee - royalty        → 立刻打给卖家
 *
 * 四个必须做对的细节：
 *
 *   1) 顺序：先算 fee，再算 royalty，剩下的全是卖家的。
 *      这样 royalty 再大也不会让卖家那一份算成负数（下溢 panic 0x11）。
 *
 *   2) 用 ERC165 检测，而不是无脑调用。
 *      if (IERC165(nft).supportsInterface(0x2a55205a)) { (receiver, amount) = royaltyInfo(...) }
 *      早期 NFT（CryptoPunks、2021 年前的合集）没有 royaltyInfo，
 *      直接调用会 revert，导致这些 NFT 在本市场完全无法成交。
 *      检测失败 → royalty = 0，交易照常进行，这叫【优雅降级】。
 *
 *   3) Pull Payment 而非 push。
 *      若在 buy() 里直接把版税转给 receiver：
 *        · receiver 是拒收 ETH 的合约 → 整笔成交 revert（DoS，卖家被连坐）
 *        · receiver 的 fallback 很耗 gas → 买家 gas 被吃光
 *        · receiver 在 fallback 里做手脚 → 多一个重入面
 *      所以版税只累加到 pendingRoyalties[receiver]，由 receiver 自己来 withdrawRoyalties()。
 *      它拒收，只影响它自己提现，不影响市场成交。
 *
 *   4) 恶意 NFT 合约的防御。
 *      royaltyInfo 是 NFT 合约自己实现的，它可以返回：
 *        · 一个黑洞地址（钱取不出来）→ 我们拦不住，也不该拦，这是创作者自己设的
 *        · 一个超过成交价的金额（10000 bps = 100%，甚至写死返回 type(uint256).max）
 *          → 不处理的话 price - fee - royalty 会下溢 panic，该 NFT 永久无法成交（DoS）
 *      我们的处理：把版税【钳制】在 price - fee 以内，钱全给创作者、卖家拿 0，
 *      至少保证交易能进行、且三方之和仍等于 price。
 * ============================================================================
 * 四、本合约 simplification（为教学做的简化，真实市场要复杂得多）
 * ============================================================================
 *   · 只支持 ETH 计价，不支持 ERC20（如 WETH / USDC）
 *   · 同一枚 NFT 同时只能有一个挂单（但可以被多个买家同时出价）
 *   · 出价不设过期时间（真实市场用 EIP-712 签名 + 链下订单簿来做有效期）
 *   · 没有签名挂单（Seaport 用 EIP-712 签名实现零 gas 挂单）
 *   · 手续费 + 版税都是【平台自愿】的：本合约选择尊重 EIP-2981，
 *     但链上没有强制力（Blur 就曾以"可选版税"抢市场），这是商业选择不是技术问题
 *
 * ============================================================================
 * 五、出价（Offer）功能的设计取舍 —— 本轮新增
 * ============================================================================
 *
 * 挂单是「卖家定价、买家接受」；出价是「买家定价、卖家接受」。
 * 两者共用同一条成交路径（_settleSale），分账规则（平台费 + 版税 + 卖家实得）
 * 因此【只有一套实现】，不存在两套算法跑出不同结果的风险。
 *
 * 六个关键设计决策：
 *
 *   1) 出价并存，不互相挤掉
 *      _offers[nft][tokenId][bidder] = {amount, targetOwner}
 *      出价按「买家」分桶，而不是按 NFT 只存一个"最高价"。
 *      好处：买家之间零干扰 —— 若只保留最高价，A 出价被 B 超过时就要给 A 退款，
 *      退款即一次 push 调用，恶意买家拒收就能把整个出价流程卡死（DoS）。
 *
 *   2) ETH 由合约代管（escrow）
 *      出价时 msg.value 真的进合约，这是出价与"签名出价"的本质区别：
 *      签名出价可以随时反悔（买家不履约），代管的 ETH 则是有约束力的承诺。
 *      代价是合约持有资金，所以必须严格保证【任何人的钱都能被取回】。
 *
 *   3) 同一买家重复出价 = 累加，而不是"退回旧的、记新的"
 *      退回旧出价同样意味着一次 push；累加则永远只是记账，与他人彻底解耦，
 *      取回时一次性全额退回。想"改价"就先 withdrawOffer 再重新 makeOffer。
 *
 *   4) 拒绝出价失败时转待领池（pendingWithdrawals），绝不 revert
 *      若 rejectOffer 因为买家拒收 ETH 而整体 revert，那么任何人只要对一个 NFT
 *      出价并拒收，持有者就永远无法拒绝任何出价 —— 典型的 DoS。
 *      所以：退回失败 → 记入 pendingWithdrawals，等买家自己来 withdrawPendingFunds()。
 *
 *   5) 成交后【不】批量清退其他出价者
 *      acceptOffer 只清掉被接受的那一笔，其余买家各自 withdrawOffer。
 *      原因同上：一次循环退款里只要有一个拒收者，整笔成交就会被卡死。
 *      宁可让买家多调一次 withdrawOffer，也不能把卖家的成交权交到别人手上。
 *
 *   6) NFT 易主后旧出价自动失效
 *      出价记录里存了出价那一刻的持有者 targetOwner。
 *      acceptOffer 要求 msg.sender 既是【当前持有者】，又是【出价时的持有者】：
 *        · 旧持有者来接受 → 他已经不是持有者 → NotTokenOwner
 *        · 新持有者来接受 → 他不是出价对象   → StaleOffer
 *      这样买家不会因为 NFT 换手，而被一个"当初没想卖给他的人"强制成交。
 *      出价失效后买家随时 withdrawOffer 取回，钱不会被锁。
 *      （注：部分真实市场选择让出价跟随 NFT 存活、由新持有者决定是否接受，
 *        两种做法都有；本合约选对买家更友好的"易主即失效"。）
 * ============================================================================
 */
contract SimpleMarket is Ownable2Step, ReentrancyGuard, EIP712, Pausable {
    // ========================================================================
    // 数据结构
    // ========================================================================

    /// @notice 一条挂单记录
    /// @param seller 卖家地址
    /// @param price  售价（wei）
    /// @param active 是否有效。撤单/成交后置 false，而不是删除记录
    ///               （保留历史记录便于链下索引，也能省 gas：删除 mapping 的退款收益有限）
    struct Listing {
        address seller;
        uint256 price;
        bool active;
    }

    // ========================================================================
    // 状态变量
    // ========================================================================

    /// @notice 平台手续费（基点）：10000 = 100%，250 = 2.5%
    uint256 public feeBps;

    /// @notice 累计待提取的手续费（单位 wei）
    uint256 public accumulatedFees;

    /// @notice 待提取的版税：版税接收者 => 累计金额（wei）
    ///         与手续费一样是 Pull Payment 设计，见 _splitProceeds 的说明
    mapping(address => uint256) public pendingRoyalties;

    /// @notice 手续费硬上限 10%，防止 owner 设成离谱的值
    uint256 public constant MAX_FEE_BPS = 1000;

    /// @notice 基点分母
    uint256 private constant BPS_DENOMINATOR = 10_000;

    /// @notice EIP-2981 的 interfaceId（0x2a55205a）
    ///         硬编码常量只是为了省一次外部调用；语义上等价于
    ///         type(IERC2981).interfaceId，测试里会断言两者一致
    bytes4 private constant INTERFACE_ID_ERC2981 = 0x2a55205a;

    /// @notice 一条出价记录
    /// @param amount      该买家当前托管在市场里的出价总额（wei）。0 表示无有效出价
    /// @param targetOwner 出价那一刻该 NFT 的持有者。
    ///                    用于实现"NFT 易主后旧出价自动失效"：
    ///                    acceptOffer 要求接受者既是当前持有者、又是 targetOwner
    struct Offer {
        uint256 amount;
        address targetOwner;
    }

    /// @notice 出价表：NFT 合约地址 => tokenId => 出价人 => 出价
    ///         按出价人分桶，所以同一枚 NFT 可以被任意多个人同时出价，互不挤掉
    mapping(address => mapping(uint256 => mapping(address => Offer))) private _offers;

    /// @notice 待领池：因原路退回失败而暂存、等账户自己来取的 ETH
    ///         场景：rejectOffer 时买家是拒收 ETH 的合约，退回失败又不能 revert，
    ///               于是把钱记在这里，由买家主动 withdrawPendingFunds() 领走
    ///         （与 pendingRoyalties 同属 Pull Payment，只是成因不同）
    mapping(address => uint256) public pendingWithdrawals;

    /// @notice 挂单表：NFT 合约地址 => tokenId => 挂单
    ///         这样设计使得一个市场可以服务任意多个 NFT 合集
    mapping(address => mapping(uint256 => Listing)) private _listings;

    // ========================================================================
    // EIP-712 链下签名挂单（ListingIntent）
    //
    // 传统 list() 要求卖家先发一笔链上交易写挂单，改价、下架也各要一笔。
    // 改成链下签名后：卖家只在链下对一条「我愿意以 X 价卖出」的意图签名，
    // 买家（或任意撮合方）拿着签名来 fulfillListing 成交，**卖家全程零 gas**。
    // 想改价 / 下架？在链下数据库里撤掉签名即可（零成本）；
    // 需要紧急作废全部签名时，再花一笔交易 incrementNonce() 让旧签名集体失配。
    // 这是 OpenSea Seaport、Blur 等主流市场的核心机制。
    // ========================================================================

    /// @notice 一条链下挂单意图（卖家在链下对它的 EIP-712 摘要签名）
    /// @param nftContract 要卖的 NFT 合约
    /// @param tokenId     要卖的 NFT 编号
    /// @param price       售价（wei）
    /// @param deadline    签名过期时间（Unix 秒），防止签名被无限期利用
    /// @param nonce       卖家的挂单 nonce，必须等于链上 listingNonces[seller]；
    ///                    成交后自动 +1，因此同一条签名**只能成交一次**（防重放）
    struct ListingIntent {
        address nftContract;
        uint256 tokenId;
        uint256 price;
        uint256 deadline;
        uint256 nonce;
    }

    /// @notice ListingIntent 的 EIP-712 typeHash。
    ///         测试里会用 keccak256 重算一遍断言相等 —— 结构体字段一改动，
    ///         这个常量不同步更新就会导致所有签名验证失效，属于硬约束
    bytes32 public constant LISTING_INTENT_TYPEHASH =
        keccak256(
            "ListingIntent(address nftContract,uint256 tokenId,uint256 price,uint256 deadline,uint256 nonce)"
        );

    /// @notice 每个卖家的挂单 nonce：成交一次 +1，卖家也可主动 +1 批量作废旧签名
    mapping(address => uint256) public listingNonces;

    // ========================================================================
    // 事件（前端与市场活动流全部依赖它们）
    // ========================================================================

    event Listed(address indexed nftContract, uint256 indexed tokenId, address indexed seller, uint256 price);
    event PriceUpdated(address indexed nftContract, uint256 indexed tokenId, uint256 oldPrice, uint256 newPrice);
    event Canceled(address indexed nftContract, uint256 indexed tokenId, address indexed seller);
    event Sold(
        address indexed nftContract,
        uint256 indexed tokenId,
        address indexed seller,
        address buyer,
        uint256 price,
        uint256 fee
    );
    event FeeBpsUpdated(uint256 oldFeeBps, uint256 newFeeBps);
    event FeesWithdrawn(address indexed to, uint256 amount);

    /// @notice 一笔成交产生了版税。注意：这是【入账】事件，不是"已打款"——
    ///         钱此刻仍在市场合约里，等 receiver 调 withdrawRoyalties() 才真正转走
    event RoyaltyPaid(
        address indexed nftContract,
        uint256 indexed tokenId,
        address indexed receiver,
        uint256 amount
    );

    /// @notice 版税接收者成功提走版税
    event RoyaltyWithdrawn(address indexed receiver, uint256 amount);

    /// @notice 有人对某枚 NFT 出价（或加价）。added 是本次追加额，total 是该买家累计托管额
    event OfferMade(
        address indexed nftContract,
        uint256 indexed tokenId,
        address indexed bidder,
        uint256 added,
        uint256 total
    );

    /// @notice 买家主动取回自己的出价
    event OfferWithdrawn(
        address indexed nftContract,
        uint256 indexed tokenId,
        address indexed bidder,
        uint256 amount
    );

    /// @notice 持有者拒绝了一笔出价。refunded=false 表示原路退回失败、钱已转入待领池
    event OfferRejected(
        address indexed nftContract,
        uint256 indexed tokenId,
        address indexed bidder,
        uint256 amount,
        bool refunded
    );

    /// @notice 持有者接受了一笔出价（紧随其后还会发出 Sold 事件，走的是同一条成交路径）
    event OfferAccepted(
        address indexed nftContract,
        uint256 indexed tokenId,
        address indexed seller,
        address bidder,
        uint256 price,
        uint256 fee
    );

    /// @notice 一笔退款原路退回失败，已转入待领池等收款人自取
    event RefundPending(address indexed account, uint256 amount);

    /// @notice 有人从待领池取走了 ETH
    event PendingWithdrawn(address indexed account, uint256 amount);

    /// @notice 卖家主动作废旧签名：nonce 跳跃后，它此前签的所有 ListingIntent 全部失配
    event NonceIncremented(address indexed seller, uint256 oldNonce, uint256 newNonce);

    // ========================================================================
    // 自定义错误
    // ========================================================================

    error PriceMustBeGreaterThanZero();
    error NotTokenOwner();
    error MarketNotApproved();
    error AlreadyListed();
    error NotListed();
    error NotSeller();
    error InsufficientPayment(uint256 sent, uint256 required);
    error StaleListing(address currentOwner, address listingSeller);
    error FeeTooHigh(uint256 provided, uint256 max);
    error EthTransferFailed();
    error NothingToWithdraw();
    error ZeroAddress();
    error RoyaltyTransferFailed();

    /// @notice 出价金额为 0（makeOffer 必须带 value > 0）
    error OfferAmountZero();

    /// @notice 该买家在这枚 NFT 上没有有效出价（撤回 / 接受 / 拒绝时）
    error NoActiveOffer();

    /// @notice 出价已因 NFT 易主而失效：currentOwner 不是出价时的对象 offerOwner
    error StaleOffer(address currentOwner, address offerOwner);

    // ---------- EIP-712 链下签名挂单 ----------

    /// @notice 签名已过期（当前区块时间已超过 intent.deadline）
    error SignatureExpired(uint256 deadline, uint256 currentTime);

    /// @notice nonce 不匹配：签名可能被重放，或 seller 已主动作废过
    error InvalidNonce(uint256 expected, uint256 provided);

    /// @notice 签名无效：恢复出的签名者不是声称的 seller，或数据被篡改
    error InvalidSignature();

    /// @notice 链下挂单意图的售价为 0
    error IntentPriceZero();

    // ========================================================================
    // 构造函数
    // ========================================================================

    /**
     * @param initialOwner 市场 owner（可提取手续费、可调费率）
     * @param feeBps_      初始手续费（基点）
     */
    constructor(
        address initialOwner,
        uint256 feeBps_
    ) Ownable(initialOwner) EIP712("SimpleMarket", "1") {
        _setFeeBps(feeBps_);
    }

    // ========================================================================
    // 卖家侧：挂单 / 改价 / 撤单
    // ========================================================================

    /**
     * @notice 挂单出售一枚 NFT
     * @param nftContract NFT 合约地址
     * @param tokenId     要卖的 NFT 编号
     * @param price       售价（wei）
     *
     * 前置条件（三个都要满足，否则 revert）：
     *   1. msg.sender 是当前持有者
     *   2. 本市场合约已被授权操作这枚 NFT（approve 或 setApprovalForAll）
     *   3. 价格 > 0
     *
     * 注意：本函数【不转移】NFT，它只在链上记一条「我愿意以这个价卖」的记录。
     *      真正做到「钱货两清」的是 buy()。
     */
    function list(address nftContract, uint256 tokenId, uint256 price) external whenNotPaused {
        if (price == 0) revert PriceMustBeGreaterThanZero();

        IERC721 nft = IERC721(nftContract);

        // 检查 1：调用者必须是持有者
        if (nft.ownerOf(tokenId) != msg.sender) revert NotTokenOwner();

        // 检查 2：市场必须已被授权，否则成交时转不动
        // getApproved 只覆盖单枚授权，还要看全量授权，两者满足其一即可
        bool approved = nft.getApproved(tokenId) == address(this) ||
            nft.isApprovedForAll(msg.sender, address(this));
        if (!approved) revert MarketNotApproved();

        // 检查 3：不能重复挂单（同一枚同时只能有一个有效挂单）
        if (_listings[nftContract][tokenId].active) revert AlreadyListed();

        _listings[nftContract][tokenId] = Listing({seller: msg.sender, price: price, active: true});

        emit Listed(nftContract, tokenId, msg.sender, price);
    }

    /**
     * @notice 修改挂单价格
     * @dev 只改价格，不重新校验授权与持有状态 —— 这是一处刻意的简化。
     *      真实市场里改价通常要求重新校验，否则可能出现「已转走 NFT 还能改价」的脏数据。
     *      成交时 buy() 会兜底校验持有者，所以不会造成资金损失。
     */
    function updatePrice(address nftContract, uint256 tokenId, uint256 newPrice) external whenNotPaused {
        Listing storage listing = _listings[nftContract][tokenId];
        if (!listing.active) revert NotListed();
        if (listing.seller != msg.sender) revert NotSeller();
        if (newPrice == 0) revert PriceMustBeGreaterThanZero();

        uint256 oldPrice = listing.price;
        listing.price = newPrice;

        emit PriceUpdated(nftContract, tokenId, oldPrice, newPrice);
    }

    /**
     * @notice 撤销挂单
     * @dev 重要：撤单【不会】自动撤销你对市场的授权。
     *      链上授权还在，市场合约理论上仍能转走你的 NFT。
     *      要彻底收回权限，请自己调用：
     *        nft.approve(address(0), tokenId)              // 单枚
     *        nft.setApprovalForAll(market, false)          // 全量
     *      这正是上一轮练的重点：全量授权不会自动过期。
     */
    function cancel(address nftContract, uint256 tokenId) external {
        Listing storage listing = _listings[nftContract][tokenId];
        if (!listing.active) revert NotListed();
        if (listing.seller != msg.sender) revert NotSeller();

        listing.active = false;

        emit Canceled(nftContract, tokenId, msg.sender);
    }

    // ========================================================================
    // 买家侧：购买
    // ========================================================================

    /**
     * @notice 购买一枚已挂单的 NFT
     * @param nftContract NFT 合约地址
     * @param tokenId     要买的 NFT 编号
     *
     * 执行顺序严格遵循 Checks-Effects-Interactions：
     *   Checks      校验挂单有效、钱够、持有者没变
     *   Effects     立刻把挂单置为失效、累加手续费（先改状态！）
     *   Interactions 然后才做外部调用：转 NFT、付钱、退款
     *
     * 为什么顺序如此关键 —— 见上方「三、1) 重入攻击」。
     */
    function buy(address nftContract, uint256 tokenId) external payable nonReentrant whenNotPaused {
        Listing storage listing = _listings[nftContract][tokenId];

        /* ---------------- Checks（检查） ---------------- */
        if (!listing.active) revert NotListed();
        if (msg.value < listing.price) {
            revert InsufficientPayment(msg.value, listing.price);
        }

        address seller = listing.seller;
        uint256 price = listing.price;

        // 防御陈旧挂单：卖家可能已经把 NFT 转走，或撤销了授权
        address currentOwner = IERC721(nftContract).ownerOf(tokenId);
        if (currentOwner != seller) {
            revert StaleListing(currentOwner, seller);
        }

        /* ---------------- Effects（改状态） ---------------- */
        // 先置失效再转账 —— 这样即使后面有重入，也进不到这里
        listing.active = false;

        /* ---------------- Interactions（外部调用） ---------------- */
        // 分账、转 NFT、给卖家打款，全部收敛到 _settleSale：
        // 它与 acceptOffer 共用同一套实现，保证"买挂单"和"接受出价"的分账结果完全一致，
        // 不会出现两套算法各算各的、某天算不一致的经典事故
        _settleSale(nftContract, tokenId, seller, msg.sender, price);

        // 多付的钱退给买家
        uint256 excess = msg.value - price;
        if (excess > 0) {
            (bool refundOk, ) = payable(msg.sender).call{value: excess}("");
            if (!refundOk) revert EthTransferFailed();
        }
    }

    // ========================================================================
    // 买家侧：凭卖家的链下签名直接成交（EIP-712 ListingIntent）
    //
    //   list() + buy()   —— 卖家先付 gas 写挂单，买家再付 gas 成交（两次链上写）
    //   fulfillListing() —— 卖家只签名（零 gas、零链上痕迹），买家一次成交搞定
    //
    // 两者共用 _settleSale，分账规则完全一致，不存在两套算法各算各的隐患。
    // ========================================================================

    /**
     * @notice 用卖家的链下签名直接买下一枚 NFT
     * @param intent    卖家的挂单意图（原文，合约重新哈希后验签）
     * @param seller    声称的卖家地址（签名者应当就是它）
     * @param signature EIP-712 签名（65 字节标准格式，或 EIP-2098 紧凑格式）
     *
     * 为什么 seller 要单独传、而不是直接用验签恢复出的地址？
     *   因为验签只能证明「某个地址签了这段数据」，不能证明「这个地址就是卖家」。
     *   必须先显式声明期望的签名者，再校验持有状态与授权 —— 这是标准做法。
     *
     * 为什么用 SignatureChecker 而不是裸 ECDSA.recover？
     *   它同时支持 EOA（ECDSA 恢复）和 ERC-1271 智能合约钱包（回调 isValidSignature），
     *   一个函数覆盖两类账户，且自带对签名可塑性（malleability）的防护。
     */
    function fulfillListing(
        ListingIntent calldata intent,
        address seller,
        bytes calldata signature
    ) external payable nonReentrant whenNotPaused {
        /* ---------------- Checks（检查） ---------------- */
        if (intent.price == 0) revert IntentPriceZero();
        if (block.timestamp > intent.deadline) {
            revert SignatureExpired(intent.deadline, block.timestamp);
        }

        uint256 expectedNonce = listingNonces[seller];
        if (intent.nonce != expectedNonce) {
            revert InvalidNonce(expectedNonce, intent.nonce);
        }

        // 验签：摘要里包含【域分隔符】——chainId + 本合约地址。
        // 因此一条签名只在签发它的那条链、这个市场合约上有效，
        // 天然具备防跨链重放、防跨市场重放的能力，无需额外编码
        bytes32 digest = _hashIntent(intent);
        if (!SignatureChecker.isValidSignatureNow(seller, digest, signature)) {
            revert InvalidSignature();
        }

        if (msg.value < intent.price) {
            revert InsufficientPayment(msg.value, intent.price);
        }

        IERC721 nft = IERC721(intent.nftContract);

        // 与 list() 相同的两道前置校验：持有者 + 授权。
        // 链下签名绕过了 list()，所以这些检查必须在成交时补上，一个都不能省
        if (nft.ownerOf(intent.tokenId) != seller) revert NotTokenOwner();

        bool approved = nft.getApproved(intent.tokenId) == address(this) ||
            nft.isApprovedForAll(seller, address(this));
        if (!approved) revert MarketNotApproved();

        /* ---------------- Effects（改状态） ---------------- */
        // 先消耗 nonce 再成交：即使后面外部调用里有人重入，
        // 同一条签名也用不了第二次（重入 + 重放的双重防护）
        listingNonces[seller] = expectedNonce + 1;

        /* ---------------- Interactions（外部调用） ---------------- */
        _settleSale(intent.nftContract, intent.tokenId, seller, msg.sender, intent.price);

        // 多付的钱退给买家
        uint256 excess = msg.value - intent.price;
        if (excess > 0) {
            (bool refundOk, ) = payable(msg.sender).call{value: excess}("");
            if (!refundOk) revert EthTransferFailed();
        }
    }

    /**
     * @notice 卖家主动把自己的挂单 nonce +1，一次性作废所有未成交的链下签名
     * @dev 这是链下挂单的「紧急下架」手段：
     *      签名只存在于链下，合约无法主动删除它们，只能靠 nonce 跳跃让旧签名集体失配。
     *      日常改价 / 下架根本不需要这一步 —— 在链下数据库里撤掉签名即可，零成本。
     */
    function incrementNonce() external {
        uint256 oldNonce = listingNonces[msg.sender];
        uint256 newNonce = oldNonce + 1;
        listingNonces[msg.sender] = newNonce;
        emit NonceIncremented(msg.sender, oldNonce, newNonce);
    }

    /// @notice 计算一条 ListingIntent 的 EIP-712 摘要（前端与测试可直接调用来对齐）
    function hashListingIntent(ListingIntent calldata intent) external view returns (bytes32) {
        return _hashIntent(intent);
    }

    /// @dev 内部：把 intent 编码后套上本合约的 EIP-712 域分隔符
    function _hashIntent(ListingIntent calldata intent) private view returns (bytes32) {
        return _hashTypedDataV4(
            keccak256(
                abi.encode(
                    LISTING_INTENT_TYPEHASH,
                    intent.nftContract,
                    intent.tokenId,
                    intent.price,
                    intent.deadline,
                    intent.nonce
                )
            )
        );
    }

    // ========================================================================
    // 买家侧：出价（Offer）
    //
    // 与挂单方向相反：挂单是卖家定价等买家接受，出价是买家定价等持有者接受。
    // 两者的成交结算走同一个 _settleSale，所以版税、平台费规则天然一致。
    // ========================================================================

    /**
     * @notice 对任意一枚 NFT 出价（ETH 随交易进入合约代管）
     * @param nftContract NFT 合约地址
     * @param tokenId     目标 NFT 编号
     *
     * 设计要点：
     *   1) 出价按买家分桶（_offers[nft][tokenId][bidder]），多人同时出价互不挤掉。
     *      若改成"只保留最高价"，那么有人加价时就必须给上一位退款 ——
     *      一次 push 调用，拒收 ETH 的恶意买家能把整个出价流程卡死。
     *
     *   2) 同一买家重复出价 = 累加（加价），同样是为了避免出现退款 push。
     *      想改成更低的价格：先 withdrawOffer 取回，再重新 makeOffer。
     *
     *   3) 这里【没有】nonReentrant，不是忘了加，而是确实不需要：
     *      函数体里唯一的外部调用是 IERC721.ownerOf，而它在接口里声明为 view，
     *      Solidity 会用 STATICCALL 去调 —— 被调用方禁止改状态、禁止转账，
     *      自然也没法回头调用本合约的任何写函数（重入面为零）。
     *      反面案例见 withdrawOffer / rejectOffer：那里要转 ETH，用的是 CALL，
     *      对方能在 receive 里回来，所以那两个函数必须加锁。
     *      （判断要不要加锁看的是"用的是 CALL 还是 STATICCALL"，不是"有没有 external 调用"）
     *
     *   4) 不校验 NFT 是否存在 / 是否被挂单：出价是买家的单方意思表示，
     *      对不存在的 tokenId 出价也只是浪费自己的钱（且随时可取回），
     *      无需让合约替买家做判断，更不该因此 revert。
     *      代价：对不存在 token 出价时 ownerOf 会 revert，这里直接透传该错误。
     */
    function makeOffer(address nftContract, uint256 tokenId) external payable whenNotPaused {
        if (msg.value == 0) revert OfferAmountZero();

        Offer storage offer = _offers[nftContract][tokenId][msg.sender];

        // 第一次出价时记录当时的持有者 —— 这是"易主即失效"的依据（见 acceptOffer）
        if (offer.amount == 0) {
            offer.targetOwner = IERC721(nftContract).ownerOf(tokenId);
        }
        offer.amount += msg.value;

        emit OfferMade(nftContract, tokenId, msg.sender, msg.value, offer.amount);
    }

    /**
     * @notice 买家取回自己在某枚 NFT 上的出价（全额）
     *
     * 为什么这里退款失败要 revert，而 rejectOffer 失败只是转待领池？
     *   因为调用者就是收款人本人：他若拒收，整笔交易回滚，
     *   钱仍好好记在他的出价里，随时可以再试一次 —— 不产生任何损失，
     *   也不需要额外的待领池记账（少一份状态，少一个出 bug 的地方）。
     */
    function withdrawOffer(address nftContract, uint256 tokenId) external nonReentrant {
        Offer storage offer = _offers[nftContract][tokenId][msg.sender];

        /* ---------------- Checks ---------------- */
        uint256 amount = offer.amount;
        if (amount == 0) revert NoActiveOffer();

        /* ---------------- Effects ---------------- */
        // 先清零再转账：即使收款方在 receive 里重入 withdrawOffer，
        // 第二次进来读到的 amount 已经是 0，会在上面的检查处失败
        offer.amount = 0;
        offer.targetOwner = address(0);

        /* ---------------- Interactions ---------------- */
        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert EthTransferFailed();

        emit OfferWithdrawn(nftContract, tokenId, msg.sender, amount);
    }

    /**
     * @notice 持有者拒绝一笔出价，尝试原路退回；买家拒收则转入待领池，绝不 revert
     * @param bidder 要拒绝的出价人
     *
     * 【为什么这里绝不能 revert】
     *   如果退回失败就让整笔交易回滚，那么任何人只要用一个拒收 ETH 的合约
     *   对某枚 NFT 出价，就能让持有者永远无法拒绝任何出价 ——
     *   持有者的资产处置权被一个无关地址劫持，这就是 DoS（拒绝服务）。
     *
     * 【退回失败后的钱去哪了】
     *   记入 pendingWithdrawals[bidder]，等买家自己调 withdrawPendingFunds() 领走。
     *   所谓 Pull Payment：把"我能不能收到钱"和"别人的操作能不能成功"彻底解耦。
     *
     * 【谁有权拒绝】
     *   当前持有者（ownerOf == msg.sender）。注意这里【不】校验 targetOwner：
     *   NFT 易主后新持有者去拒绝一笔陈旧的出价，效果是帮买家把钱退回去，
     *   对所有人都是好事，没有理由禁止。
     */
    function rejectOffer(
        address nftContract,
        uint256 tokenId,
        address bidder
    ) external nonReentrant {
        /* ---------------- Checks ---------------- */
        if (bidder == address(0)) revert ZeroAddress();
        if (IERC721(nftContract).ownerOf(tokenId) != msg.sender) revert NotTokenOwner();

        Offer storage offer = _offers[nftContract][tokenId][bidder];
        uint256 amount = offer.amount;
        if (amount == 0) revert NoActiveOffer();

        /* ---------------- Effects ---------------- */
        offer.amount = 0;
        offer.targetOwner = address(0);

        /* ---------------- Interactions ---------------- */
        (bool ok, ) = payable(bidder).call{value: amount}("");
        if (!ok) {
            // 买家（或它那个会 revert 的合约）拒收 —— 不 revert，改走待领池
            pendingWithdrawals[bidder] += amount;
            emit RefundPending(bidder, amount);
        }

        emit OfferRejected(nftContract, tokenId, bidder, amount, ok);
    }

    /**
     * @notice 持有者接受一笔出价，立刻成交
     * @param bidder 要接受的出价人
     *
     * 校验四件事：
     *   1. msg.sender 是当前持有者          → 否则 NotTokenOwner
     *   2. 出价对象就是 msg.sender          → 否则 StaleOffer（NFT 已易主，旧出价失效）
     *   3. 市场已被授权转这枚 NFT           → 否则 MarketNotApproved
     *   4. 该买家确实有一笔有效出价         → 否则 NoActiveOffer
     *
     * 成交后【只清掉被接受的这一笔】，其他出价者的钱留在合约里等他们自己取回。
     * 刻意不做批量退款：一次循环里只要有一个人拒收，整笔成交就会被卡死。
     */
    function acceptOffer(
        address nftContract,
        uint256 tokenId,
        address bidder
    ) external nonReentrant whenNotPaused {
        IERC721 nft = IERC721(nftContract);

        /* ---------------- Checks ---------------- */
        if (nft.ownerOf(tokenId) != msg.sender) revert NotTokenOwner();

        Offer storage offer = _offers[nftContract][tokenId][bidder];
        if (offer.targetOwner != msg.sender) {
            // NFT 已经易主：新持有者不是当初被出价的那个人，旧出价自动失效。
            // 买家随时可以 withdrawOffer 把钱取回，不会被锁在这里
            revert StaleOffer(msg.sender, offer.targetOwner);
        }

        // 授权是成交的前提：没有它 safeTransferFrom 会失败，
        // 但那种失败信息对新手极不友好，所以提前用业务错误挡掉
        bool approved = nft.getApproved(tokenId) == address(this) ||
            nft.isApprovedForAll(msg.sender, address(this));
        if (!approved) revert MarketNotApproved();

        // 这里【不需要】再判 price > 0：出价记录被清空时 targetOwner 会一并归零，
        // 所以能走到这一步的必然是"targetOwner == msg.sender 且 amount > 0"的有效出价。
        // 顺带说明：校验顺序（持有者 → 是否易主 → 授权）本身就是一条完整的存在性检查，
        // 多写一句死代码反而误导读者。
        uint256 price = offer.amount;

        /* ---------------- Effects ---------------- */
        // 先清掉这笔出价再成交：恶意买家若在 safeTransferFrom 的回调里重入
        // acceptOffer，会在 NoActiveOffer（乃至更早的锁）处失败，无法二次成交
        offer.amount = 0;
        offer.targetOwner = address(0);

        /* ---------------- Interactions ---------------- */
        uint256 fee = _settleSale(nftContract, tokenId, msg.sender, bidder, price);

        emit OfferAccepted(nftContract, tokenId, msg.sender, bidder, price, fee);
    }

    /**
     * @notice 从待领池取走 ETH（rejectOffer 退款失败时钱会落到这里）
     */
    function withdrawPendingFunds() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        if (amount == 0) revert NothingToWithdraw();

        pendingWithdrawals[msg.sender] = 0; // 先改状态

        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert EthTransferFailed();

        emit PendingWithdrawn(msg.sender, amount);
    }

    // ========================================================================
    // 内部：成交结算（挂单购买与接受出价共用）
    // ========================================================================

    /**
     * @notice 一笔成交的完整结算：分账 → 转 NFT → 给卖家打款
     * @param seller 卖家（挂单成交时是挂单人，接受出价时是持有者 msg.sender）
     * @param buyer  买家（挂单成交时是 msg.sender，接受出价时是出价人）
     * @return fee   本笔成交计入的平台手续费
     *
     * 这是全合约【唯一】动钱和动 NFT 的地方。
     * 把 buy() 和 acceptOffer() 的结算逻辑收敛到一处，好处是：
     *   · 不会出现两处分账算法某天不一致
     *   · 新增成交方式（比如拍卖）时，复用它即可，安全性质自动继承
     *
     * 注意它没有 nonReentrant：调用它的 buy / acceptOffer 都已经上了锁，
     * 这里再加一层锁反而会因为的重入保护的嵌套检测而直接 revert。
     * 它的安全性来自【调用方已完成 Effects】：进入本函数时，
     * 挂单 / 出价状态都已经被清掉了。
     */
    function _settleSale(
        address nftContract,
        uint256 tokenId,
        address seller,
        address buyer,
        uint256 price
    ) private returns (uint256 fee) {
        // 三方分账：平台手续费 + 创作者版税 + 卖家实得，三者之和恒等于 price
        uint256 royalty;
        address royaltyReceiver;
        uint256 sellerProceeds;
        (fee, royalty, royaltyReceiver, sellerProceeds) = _splitProceeds(nftContract, tokenId, price);

        if (fee > 0) {
            accumulatedFees += fee; // 累积起来等 owner 提取，不在这里直接转（Pull Payment）
        }

        if (royalty > 0) {
            // 版税同样只入账、不转账。receiver 拒收 ETH 时，只影响它自己提现，
            // 不会连累这笔成交失败（Push 写法下的经典 DoS 陷阱）
            pendingRoyalties[royaltyReceiver] += royalty;
            emit RoyaltyPaid(nftContract, tokenId, royaltyReceiver, royalty);
        }

        // 1) 把 NFT 转给买家。用 safe 版本：如果买家是合约且不支持 NFT，整笔回滚
        IERC721(nftContract).safeTransferFrom(seller, buyer, tokenId);

        // 2) 给卖家打款。用 call 并检查返回值，不用 transfer（2300 gas 限制会误伤合约卖家）
        (bool ok, ) = payable(seller).call{value: sellerProceeds}("");
        if (!ok) revert EthTransferFailed();

        emit Sold(nftContract, tokenId, seller, buyer, price, fee);
    }

    // ========================================================================
    // 查询
    // ========================================================================

    /// @notice 查询一条挂单
    function getListing(
        address nftContract,
        uint256 tokenId
    ) external view returns (address seller, uint256 price, bool active) {
        Listing storage l = _listings[nftContract][tokenId];
        return (l.seller, l.price, l.active);
    }

    /**
     * @notice 查询某个买家对某枚 NFT 的出价
     * @return amount      托管中的出价金额（wei）；0 表示没有有效出价
     * @return targetOwner 出价时的持有者。若它与当前持有者不一致，
     *                     说明 NFT 已易主，这笔出价已无法被接受（只能由买家取回）
     */
    function getOffer(
        address nftContract,
        uint256 tokenId,
        address bidder
    ) external view returns (uint256 amount, address targetOwner) {
        Offer storage o = _offers[nftContract][tokenId][bidder];
        return (o.amount, o.targetOwner);
    }

    // ========================================================================
    // 分账逻辑（手续费 + 版税 + 卖家实得）
    // ========================================================================

    /**
     * @dev 把成交价 price 拆成三份。buy() 与 quoteWithRoyalty() 共用它，
     *      保证"前端看到的预估"和"链上真实执行的"永远是同一套算法。
     *
     * 三条不变量（测试里逐条断言）：
     *   1. fee + royalty + sellerProceeds == price      一分钱不多、一分钱不少
     *   2. sellerProceeds >= 0                          绝不下溢
     *   3. 整数除法的余数（最多 2 wei）全部落进 sellerProceeds
     *
     * @return fee            平台手续费
     * @return royalty        创作者版税（不支持 2981 / 未设版税时为 0）
     * @return royaltyReceiver 版税收款方（无版税时为 address(0)）
     * @return sellerProceeds 卖家实得
     */
    function _splitProceeds(
        address nftContract,
        uint256 tokenId,
        uint256 price
    ) private view returns (uint256 fee, uint256 royalty, address royaltyReceiver, uint256 sellerProceeds) {
        // 平台手续费：price * feeBps / 10000（向下取整）
        fee = (price * feeBps) / BPS_DENOMINATOR;

        // 版税：先做 ERC165 能力检测，再查报价
        if (IERC165(nftContract).supportsInterface(INTERFACE_ID_ERC2981)) {
            (address receiver, uint256 amount) = IERC2981(nftContract).royaltyInfo(tokenId, price);

            // 只有"接收者有效 且 金额大于 0"才算版税。
            // 未设版税的合集会返回 (address(0), 0) —— 走 else 分支，交易照常
            if (receiver != address(0) && amount > 0) {
                // 版税上限 = 扣掉平台费后剩下的全部。
                // 没有这个钳制，恶意/配置失误的 NFT（100% 版税）会让下面的减法下溢，
                // 导致该 NFT 在本市场永远卖不掉（panic 0x11 无法被 try/catch 捕获）
                uint256 maxRoyalty = price - fee;
                if (amount > maxRoyalty) {
                    amount = maxRoyalty;
                }

                royalty = amount;
                royaltyReceiver = receiver;
            }
        }

        // 卖家拿剩下的全部（含取整余数）。royalty <= price - fee，所以不会下溢
        sellerProceeds = price - fee - royalty;
    }

    /**
     * @notice 前端专用：预估一笔成交的三方分账，纯 view 不花 gas
     * @param nftContract NFT 合约地址
     * @param tokenId     要买的 NFT 编号
     * @param price       假设的成交价（wei）
     */
    function quoteWithRoyalty(
        address nftContract,
        uint256 tokenId,
        uint256 price
    )
        external
        view
        returns (uint256 fee, uint256 royalty, address royaltyReceiver, uint256 sellerProceeds)
    {
        return _splitProceeds(nftContract, tokenId, price);
    }

    // ========================================================================
    // 版税收款方：提取
    // ========================================================================

    /**
     * @notice 提取属于 msg.sender 的版税（Pull Payment 的另一半）
     *
     * 与 withdrawFees 的两点不同：
     *   1. 没有 onlyOwner —— 谁被 NFT 指定为版税接收者，谁就能提自己的那一份
     *   2. 没有 ZeroAddress 校验 —— msg.sender 不可能是零地址，
     *      而允许"提到别的地址"反而会把别人的版税转走，所以只允许提到 msg.sender
     *
     * 顺序依旧是先改状态（清零）再转账，配合 nonReentrant 防重入。
     */
    function withdrawRoyalties() external nonReentrant {
        uint256 amount = pendingRoyalties[msg.sender];
        if (amount == 0) revert NothingToWithdraw();

        pendingRoyalties[msg.sender] = 0; // 先改状态

        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        if (!ok) revert RoyaltyTransferFailed();

        emit RoyaltyWithdrawn(msg.sender, amount);
    }

    // ========================================================================
    // Owner 管理
    // ========================================================================

    /**
     * @notice 紧急暂停：阻断所有"开仓类"动作（挂单 / 改价 / 买入 / 报价 / 接受报价 / 签名成交）
     *
     * 设计要点（刻意的选择，不是遗漏）：
     *   暂停只挡"把钱和货推进新交易"的方向，而
     *   cancel / withdrawOffer / withdrawPendingFunds / withdrawRoyalties
     *   一律保持可用 —— 用户必须永远留着"把钱拿回来"的退路，
     *   紧急暂停绝不能变成冻结用户资金的开关。
     */
    function pause() external onlyOwner {
        _pause();
    }

    /// @notice 解除暂停
    function unpause() external onlyOwner {
        _unpause();
    }

    /// @notice 调整手续费（受 MAX_FEE_BPS 上限约束）
    function setFeeBps(uint256 newFeeBps) external onlyOwner {
        _setFeeBps(newFeeBps);
    }

    /**
     * @notice 提取累计手续费
     * @param to 收款地址
     *
     * 这就是 Pull Payment：钱一直躺在合约里，owner 主动来取。
     * 对比直接 push 给 owner 的做法，它把「owner 收不收款」和「市场能不能正常成交」
     * 这两件事彻底解耦 —— 即使 owner 地址出问题，用户的买卖也不受影响。
     */
    function withdrawFees(address to) external onlyOwner nonReentrant {
        if (to == address(0)) revert ZeroAddress();
        uint256 amount = accumulatedFees;
        if (amount == 0) revert NothingToWithdraw();

        accumulatedFees = 0; // 先改状态再转账，防重入

        (bool ok, ) = payable(to).call{value: amount}("");
        if (!ok) revert EthTransferFailed();

        emit FeesWithdrawn(to, amount);
    }

    /// @dev 内部设置费率，带上限校验
    function _setFeeBps(uint256 newFeeBps) private {
        if (newFeeBps > MAX_FEE_BPS) revert FeeTooHigh(newFeeBps, MAX_FEE_BPS);
        uint256 old = feeBps;
        feeBps = newFeeBps;
        emit FeeBpsUpdated(old, newFeeBps);
    }

    /*
     * ==========================================================================
     * 【知识点】为什么用 call 而不是 transfer / send
     * ==========================================================================
     *   addr.transfer(x)   —— 固定转发 2300 gas，够发个日志，不够做任何逻辑
     *   addr.send(x)       —— 同 2300 gas，但失败不 revert，只返回 false（易被忽略）
     *   addr.call{value:x}("") —— 转发剩余全部 gas，返回 (bool, bytes)
     *
     * 2300 gas 的问题：如果收款方是合约（多签钱包、某些市场合约、Gnosis Safe），
     * 它的 fallback 稍微复杂一点就会 out of gas，导致整个交易失败。
     * 历史上多起因使用 transfer 导致资金卡死的案例。
     *
     * 当前最佳实践：用 call，然后【必须】检查返回值。
     * 至于 call 带来的重入风险，用 nonReentrant + 先改状态来防，而不是靠限制 gas。
     *
     * 同理，本合约转 NFT 用 safeTransferFrom 而不是 transferFrom：
     * 前者在接收方是合约时会校验它是否支持 NFT，防止资产被锁死。
     * 代价是多一次外部调用、gas 略高（你上一轮实测约 +5,500 gas）。
     * ==========================================================================
     */
}
